// Generated by tests/compile_revised_tests.py; retain both published editions.
(function(){const d=window.L4_TEST_DATA;if(!d||d.revision!=="2026-11-12-tests-2"||d.tests.length!==40)throw Error("Revised test pack order incomplete");d.tests.push(...[{"id":"T41","title":"B1 · Safe & Secure Working Environment","description":"Secure habits in ordinary analytical work and collaboration.","questions":[{"ksb":"B1","objective":"Meeting preparation","prompt":"You will demonstrate a report to external attendees. Which preparation supports professional, secure working?","options":[{"text":"Keep authentication details out of the demonstration","why":"A realistic demonstration still needs an authorised audience and suitable data; permitted sanitised or synthetic material can demonstrate the report's behaviour.","correct":true,"id":"A"},{"text":"Verify what the audience is authorised to receive","why":"Attendance does not establish entitlement to every underlying record.","correct":true,"id":"B"},{"text":"Use a recent production extract for realism before verifying the external attendees' permissions","why":"A realistic demonstration still needs an authorised audience and suitable data; permitted sanitised or synthetic material can demonstrate the report's behaviour.","correct":false,"id":"C"},{"text":"Use permitted sanitised or synthetic material","why":"Displaying information can disclose it even without transferring a file.","correct":true,"id":"D"},{"text":"Check drill-through, downloads and notifications","why":"Additional interactions or notifications can reveal information beyond the opening view.","correct":true,"id":"E"},{"text":"Treat an invitation to the meeting as source-data access approval","why":"Attendance does not establish entitlement to every underlying record.","correct":false,"id":"F"},{"text":"Assume a screen share does not count as sharing information","why":"Displaying information can disclose it even without transferring a file.","correct":false,"id":"G"},{"text":"Review only the first visible chart","why":"Additional interactions or notifications can reveal information beyond the opening view.","correct":false,"id":"H"}],"answer":"Displaying information can disclose it even without transferring a file. Additional interactions or notifications can reveal information beyond the opening view. Attendance does not establish entitlement to every underlying record. A realistic demonstration still needs an authorised audience and suitable data; permitted sanitised or synthetic material can demonstrate the report's behaviour.","source":{"anchor":"ksb-b1","guideSha256":"781a2807974ae0574d3dd991370c2e991c3d9c29bbae65fc61bb58ab3db4f4d1","excerpt":"Explain secure, professional habits as part of productive working: use approved devices and accounts, protect authentication, lock unattended screens, check access and recipients, use approved storage, minimise exposed information and follow incident reporting and retention rules."},"id":"T41-E2-Q01"},{"ksb":"B1","objective":"Retaining working files","prompt":"A completed project's working copies have reached their agreed disposal date. Which behaviour is appropriate?","options":[{"text":"Consider shared copies as well as your local files","why":"A shortcut is not the underlying data, and other relevant copies may remain.","correct":true,"id":"A"},{"text":"Follow the approved disposal or retention-review process","why":"Indefinite retention is not justified merely by a wish to be thorough.","correct":true,"id":"B"},{"text":"Delete only the desktop shortcut","why":"A shortcut is not the underlying data, and other relevant copies may remain.","correct":false,"id":"C"},{"text":"Retain every copy indefinitely to demonstrate diligence","why":"Indefinite retention is not justified merely by a wish to be thorough.","correct":false,"id":"D"},{"text":"Keep suitable permitted methods and audit material where needed","why":"Reproducibility does not require unnecessary public disclosure of personal information.","correct":true,"id":"E"},{"text":"Mark disposal complete before checking the relevant locations","why":"The record should accurately reflect the actual action and authority.","correct":false,"id":"F"},{"text":"Describe an unapproved delay as a permitted exception","why":"The record should accurately reflect the actual action and authority.","correct":false,"id":"G"},{"text":"Publish identifiable inputs to prove reproducibility","why":"Reproducibility does not require unnecessary public disclosure of personal information.","correct":false,"id":"H"}],"answer":"Indefinite retention is not justified merely by a wish to be thorough. A shortcut is not the underlying data, and other relevant copies may remain. Reproducibility does not require unnecessary public disclosure of personal information. The record should accurately reflect the actual action and authority.","source":{"anchor":"ksb-b1","guideSha256":"781a2807974ae0574d3dd991370c2e991c3d9c29bbae65fc61bb58ab3db4f4d1","excerpt":"Explain secure, professional habits as part of productive working: use approved devices and accounts, protect authentication, lock unattended screens, check access and recipients, use approved storage, minimise exposed information and follow incident reporting and retention rules."},"id":"T41-E2-Q02"},{"ksb":"B1","objective":"Public-facing output","prompt":"A dashboard shows safe-looking aggregates but offers a detailed CSV download. Which review demonstrates secure professional behaviour?","options":[{"text":"Remove all warnings to make the report look confident","why":"Professional presentation should not conceal material handling or interpretation limits.","correct":false,"id":"A"},{"text":"Approve the output solely from the visible chart","why":"Hidden or downloadable detail can disclose more than the initial view.","correct":false,"id":"B"},{"text":"Review permissions and disclosure treatment for the intended audience","why":"A wider audience can require different controls and release decisions.","correct":true,"id":"C"},{"text":"Treat a successful upload as the only release check","why":"Technical publication is distinct from authorised, appropriate release.","correct":false,"id":"D"},{"text":"Check what the download actually contains","why":"Hidden or downloadable detail can disclose more than the initial view.","correct":true,"id":"E"},{"text":"Follow the relevant approval and record the outcome","why":"Technical publication is distinct from authorised, appropriate release.","correct":true,"id":"F"},{"text":"Explain any limits that affect safe use","why":"Professional presentation should not conceal material handling or interpretation limits.","correct":true,"id":"G"},{"text":"Reuse internal testing access settings for public release automatically","why":"A wider audience can require different controls and release decisions.","correct":false,"id":"H"}],"answer":"Hidden or downloadable detail can disclose more than the initial view. A wider audience can require different controls and release decisions. Technical publication is distinct from authorised, appropriate release. Professional presentation should not conceal material handling or interpretation limits.","source":{"anchor":"ksb-b1","guideSha256":"781a2807974ae0574d3dd991370c2e991c3d9c29bbae65fc61bb58ab3db4f4d1","excerpt":"Explain secure, professional habits as part of productive working: use approved devices and accounts, protect authentication, lock unattended screens, check access and recipients, use approved storage, minimise exposed information and follow incident reporting and retention rules."},"id":"T41-E2-Q03"},{"ksb":"B1","objective":"Shared workstation","prompt":"You leave a shared office workstation while an identifiable extract is open. Which actions support a secure working environment?","options":[{"text":"Rely on being inside the office as the access control","why":"An internal location does not establish that every passer-by is authorised to see the data.","correct":false,"id":"A"},{"text":"Close the database connection but leave the already downloaded extract open on screen","why":"Ending authentication does not hide information already displayed. Secure working includes physical visibility as well as account controls.","correct":false,"id":"B"},{"text":"Leave the session open because the next user is also an employee","why":"Shared employment does not establish authority to use your authenticated session or view this extract; preserve individual identity and access controls.","correct":false,"id":"C"},{"text":"Lock the session before stepping away","why":"An internal location does not establish that every passer-by is authorised to see the data.","correct":true,"id":"D"},{"text":"Consider visible screens and printed material","why":"Ending authentication does not hide information already displayed. Secure working includes physical visibility as well as account controls.","correct":true,"id":"E"},{"text":"Save an extra personal-drive copy for convenience","why":"Working copies remain subject to the organisation's handling rules.","correct":false,"id":"F"},{"text":"Keep the extract within the approved workspace","why":"Working copies remain subject to the organisation's handling rules.","correct":true,"id":"G"},{"text":"Ask a colleague to share your logged-in session while you are away","why":"Shared employment does not establish authority to use your authenticated session or view this extract; preserve individual identity and access controls.","correct":false,"id":"H"}],"answer":"An internal location does not establish that every passer-by is authorised to see the data. Working copies remain subject to the organisation's handling rules. Ending authentication does not hide information already displayed. Secure working includes physical visibility as well as account controls. Shared employment does not establish authority to use your authenticated session or view this extract; preserve individual identity and access controls.","source":{"anchor":"ksb-b1","guideSha256":"781a2807974ae0574d3dd991370c2e991c3d9c29bbae65fc61bb58ab3db4f4d1","excerpt":"Explain secure, professional habits as part of productive working: use approved devices and accounts, protect authentication, lock unattended screens, check access and recipients, use approved storage, minimise exposed information and follow incident reporting and retention rules."},"id":"T41-E2-Q04"},{"ksb":"B1","objective":"Safe evidence","prompt":"You need to show how you worked securely in a portfolio. Which approach is appropriate?","options":[{"text":"List policy titles without connecting them to your activity","why":"The explanation should show practical application in the actual task.","correct":false,"id":"A"},{"text":"Claim you administered all organisational security because you used an approved account","why":"A truthful account separates your behaviour from wider responsibilities.","correct":false,"id":"B"},{"text":"Include unredacted credentials to prove system access","why":"Secure evidence can show the workflow without revealing secrets.","correct":false,"id":"C"},{"text":"Explain how the controls supported productive work","why":"The explanation should show practical application in the actual task.","correct":true,"id":"D"},{"text":"Use permitted, suitably protected references","why":"Secure evidence can show the workflow without revealing secrets.","correct":true,"id":"E"},{"text":"Describe controls you actually used","why":"Evidence should reflect genuine actions rather than an impressive fictional story.","correct":true,"id":"F"},{"text":"Invent a security incident and successful response","why":"Evidence should reflect genuine actions rather than an impressive fictional story.","correct":false,"id":"G"},{"text":"Distinguish your responsibilities from platform-team controls","why":"A truthful account separates your behaviour from wider responsibilities.","correct":true,"id":"H"}],"answer":"Evidence should reflect genuine actions rather than an impressive fictional story. Secure evidence can show the workflow without revealing secrets. A truthful account separates your behaviour from wider responsibilities. The explanation should show practical application in the actual task.","source":{"anchor":"ksb-b1","guideSha256":"781a2807974ae0574d3dd991370c2e991c3d9c29bbae65fc61bb58ab3db4f4d1","excerpt":"Explain secure, professional habits as part of productive working: use approved devices and accounts, protect authentication, lock unattended screens, check access and recipients, use approved storage, minimise exposed information and follow incident reporting and retention rules."},"id":"T41-E2-Q05"},{"ksb":"B1","objective":"Sending an extract","prompt":"You are about to send a restricted file to several colleagues. Which checks should precede the transfer?","options":[{"text":"Verify recipients and their relevant permissions","why":"Organisational membership alone does not establish a need for restricted information.","correct":true,"id":"A"},{"text":"Check the actual attachment or shared-link permissions","why":"The shared file and its permissions determine what recipients can access.","correct":true,"id":"B"},{"text":"Validate only the wording of the email","why":"The shared file and its permissions determine what recipients can access.","correct":false,"id":"C"},{"text":"Include unused identifying columns for unspecified future work","why":"Unnecessary detail increases exposure without supporting the stated need.","correct":false,"id":"D"},{"text":"Use a personal messaging service solely because it is quicker","why":"Convenience does not replace the applicable transfer requirements.","correct":false,"id":"E"},{"text":"Limit the contents to the agreed purpose","why":"Unnecessary detail increases exposure without supporting the stated need.","correct":true,"id":"F"},{"text":"Assume everyone in the same organisation needs the full file","why":"Organisational membership alone does not establish a need for restricted information.","correct":false,"id":"G"},{"text":"Use the approved channel and appropriate protection","why":"Convenience does not replace the applicable transfer requirements.","correct":true,"id":"H"}],"answer":"Organisational membership alone does not establish a need for restricted information. Convenience does not replace the applicable transfer requirements. Unnecessary detail increases exposure without supporting the stated need. The shared file and its permissions determine what recipients can access.","source":{"anchor":"ksb-b1","guideSha256":"781a2807974ae0574d3dd991370c2e991c3d9c29bbae65fc61bb58ab3db4f4d1","excerpt":"Explain secure, professional habits as part of productive working: use approved devices and accounts, protect authentication, lock unattended screens, check access and recipients, use approved storage, minimise exposed information and follow incident reporting and retention rules."},"id":"T41-E2-Q06"},{"ksb":"B1","objective":"Password request","prompt":"A colleague's access is delayed and they ask to use your account for a short task. Which response is appropriate?","options":[{"text":"Record their actions as though you performed them","why":"A secure environment depends on accurate attribution and appropriate monitoring.","correct":false,"id":"A"},{"text":"Disable logging to avoid confusing the access record","why":"A secure environment depends on accurate attribution and appropriate monitoring.","correct":false,"id":"B"},{"text":"Explain the dependency and realistic timing to affected people","why":"Clear communication supports a professional response to the constraint.","correct":true,"id":"C"},{"text":"Share the password because the task is short","why":"Duration does not resolve the identity and accountability problems of credential sharing.","correct":false,"id":"D"},{"text":"Give unrestricted access instead of checking the requested data","why":"A limited authorised alternative may meet the need without excessive permissions.","correct":false,"id":"E"},{"text":"Conceal the access delay and promise immediate completion","why":"Clear communication supports a professional response to the constraint.","correct":false,"id":"F"},{"text":"Direct them to the authorised access route","why":"Duration does not resolve the identity and accountability problems of credential sharing.","correct":true,"id":"G"},{"text":"Discuss a permitted interim output if it meets their need","why":"A limited authorised alternative may meet the need without excessive permissions.","correct":true,"id":"H"}],"answer":"Duration does not resolve the identity and accountability problems of credential sharing. A limited authorised alternative may meet the need without excessive permissions. Clear communication supports a professional response to the constraint. A secure environment depends on accurate attribution and appropriate monitoring.","source":{"anchor":"ksb-b1","guideSha256":"781a2807974ae0574d3dd991370c2e991c3d9c29bbae65fc61bb58ab3db4f4d1","excerpt":"Explain secure, professional habits as part of productive working: use approved devices and accounts, protect authentication, lock unattended screens, check access and recipients, use approved storage, minimise exposed information and follow incident reporting and retention rules."},"id":"T41-E2-Q07"},{"ksb":"B1","objective":"Uncertain permissions","prompt":"A colleague sends you an unfamiliar dataset containing potentially identifying codes. Which initial behaviour is justified?","options":[{"text":"Use approved storage and handling in the meantime","why":"Inspection still needs appropriate handling of potentially sensitive content.","correct":true,"id":"A"},{"text":"Treat numeric codes as automatically non-personal","why":"Format and size do not establish whether information can identify people.","correct":false,"id":"B"},{"text":"Avoid wider sharing while the uncertainty is resolved","why":"Uncertainty should not be resolved by unnecessarily expanding access.","correct":true,"id":"C"},{"text":"Clarify permitted use and sensitivity with the responsible owner","why":"Receiving information does not establish permission for every purpose.","correct":true,"id":"D"},{"text":"Assume receipt of the file authorises any analysis","why":"Receiving information does not establish permission for every purpose.","correct":false,"id":"E"},{"text":"Forward it to a large group for informal classification","why":"Uncertainty should not be resolved by unnecessarily expanding access.","correct":false,"id":"F"},{"text":"Infer low sensitivity from a small attachment size","why":"Format and size do not establish whether information can identify people.","correct":false,"id":"G"},{"text":"Upload it to a public conversion tool to inspect the codes","why":"Inspection still needs appropriate handling of potentially sensitive content.","correct":false,"id":"H"}],"answer":"Receiving information does not establish permission for every purpose. Uncertainty should not be resolved by unnecessarily expanding access. Inspection still needs appropriate handling of potentially sensitive content. Format and size do not establish whether information can identify people.","source":{"anchor":"ksb-b1","guideSha256":"781a2807974ae0574d3dd991370c2e991c3d9c29bbae65fc61bb58ab3db4f4d1","excerpt":"Explain secure, professional habits as part of productive working: use approved devices and accounts, protect authentication, lock unattended screens, check access and recipients, use approved storage, minimise exposed information and follow incident reporting and retention rules."},"id":"T41-E2-Q08"},{"ksb":"B1","objective":"Personal storage shortcut","prompt":"A managed workspace is temporarily slow. Which response maintains safe productivity?","options":[{"text":"Communicate any material delivery impact","why":"Professional communication lets others make realistic decisions about the dependency.","correct":true,"id":"A"},{"text":"Hide the delay and claim the work is progressing normally","why":"Professional communication lets others make realistic decisions about the dependency.","correct":false,"id":"B"},{"text":"Continue other authorised tasks while the issue is addressed","why":"Safe adaptation can preserve productivity without bypassing controls.","correct":true,"id":"C"},{"text":"Copy the restricted extract to personal storage without approval","why":"A performance problem does not authorise a different handling environment.","correct":false,"id":"D"},{"text":"Treat an informal preference as a formal policy exception","why":"Any exception needs the relevant authority and process.","correct":false,"id":"E"},{"text":"Abandon all useful work despite independent tasks being available","why":"Safe adaptation can preserve productivity without bypassing controls.","correct":false,"id":"F"},{"text":"Check for an approved alternative or support route","why":"A performance problem does not authorise a different handling environment.","correct":true,"id":"G"},{"text":"Record an authorised exception if the actual policy permits one","why":"Any exception needs the relevant authority and process.","correct":true,"id":"H"}],"answer":"A performance problem does not authorise a different handling environment. Professional communication lets others make realistic decisions about the dependency. Safe adaptation can preserve productivity without bypassing controls. Any exception needs the relevant authority and process.","source":{"anchor":"ksb-b1","guideSha256":"781a2807974ae0574d3dd991370c2e991c3d9c29bbae65fc61bb58ab3db4f4d1","excerpt":"Explain secure, professional habits as part of productive working: use approved devices and accounts, protect authentication, lock unattended screens, check access and recipients, use approved storage, minimise exposed information and follow incident reporting and retention rules."},"id":"T41-E2-Q09"},{"ksb":"B1","objective":"Incident response","prompt":"You discover that a file was shared with the wrong internal group. Which behaviour supports safe, accountable work?","options":[{"text":"Provide relevant facts through approved channels","why":"Investigation should not unnecessarily expand the exposure.","correct":true,"id":"A"},{"text":"Circulate the full file widely to ask who is affected","why":"Investigation should not unnecessarily expand the exposure.","correct":false,"id":"B"},{"text":"Follow the internal incident process promptly","why":"An identified handling problem should follow the relevant process without waiting for demonstrated harm.","correct":true,"id":"C"},{"text":"Delete the audit trail to make the workspace look tidy","why":"Containment should support, rather than undermine, an appropriate investigation.","correct":false,"id":"D"},{"text":"Follow authorised containment and preserve useful records","why":"Containment should support, rather than undermine, an appropriate investigation.","correct":true,"id":"E"},{"text":"Wait for a complaint before reporting the issue","why":"An identified handling problem should follow the relevant process without waiting for demonstrated harm.","correct":false,"id":"F"},{"text":"Declare the issue harmless solely because the group is internal","why":"Audience and consequences need assessment rather than unsupported reassurance or a premature legal conclusion.","correct":false,"id":"G"},{"text":"Announce a specific external reporting outcome without the responsible assessment","why":"Audience and consequences need assessment rather than unsupported reassurance or a premature legal conclusion.","correct":false,"id":"H"}],"answer":"An identified handling problem should follow the relevant process without waiting for demonstrated harm. Investigation should not unnecessarily expand the exposure. Containment should support, rather than undermine, an appropriate investigation. Audience and consequences need assessment rather than unsupported reassurance or a premature legal conclusion.","source":{"anchor":"ksb-b1","guideSha256":"781a2807974ae0574d3dd991370c2e991c3d9c29bbae65fc61bb58ab3db4f4d1","excerpt":"Explain secure, professional habits as part of productive working: use approved devices and accounts, protect authentication, lock unattended screens, check access and recipients, use approved storage, minimise exposed information and follow incident reporting and retention rules."},"id":"T41-E2-Q10"}]},{"id":"T42","title":"B2 · Adaptability & Problem Solving","description":"Responding constructively to minor unexpected operational changes.","questions":[{"ksb":"B2","objective":"Preserving quality","prompt":"An unexpected formatting issue consumes part of your review time. Which response balances adaptation and quality?","options":[{"text":"Prioritise essential correctness and interpretation checks","why":"Quality-critical checks should remain proportionate to the risk. A reduced check is not automatically equivalent and needs explicit evaluation when time changes.","correct":true,"id":"A"},{"text":"Replace reconciliation with a quick visual spot-check without reassessing the remaining quality risk","why":"Quality-critical checks should remain proportionate to the risk. A reduced check is not automatically equivalent and needs explicit evaluation when time changes.","correct":false,"id":"B"},{"text":"Promise unchanged scope without assessing the remaining time","why":"A realistic adjustment may be needed to maintain a reliable output.","correct":false,"id":"C"},{"text":"Report the original plan as fully completed when parts were omitted","why":"A truthful account distinguishes adaptation from an unchanged delivery.","correct":false,"id":"D"},{"text":"Explain what changed and the resulting outcome","why":"A truthful account distinguishes adaptation from an unchanged delivery.","correct":true,"id":"E"},{"text":"Treat any faster workaround as acceptable regardless of data handling","why":"Evidence and approved handling remain necessary during a minor disruption.","correct":false,"id":"F"},{"text":"Invent positive stakeholder feedback to justify the workaround","why":"Evidence and approved handling remain necessary during a minor disruption.","correct":false,"id":"G"},{"text":"Agree a reduced presentation scope if necessary","why":"A realistic adjustment may be needed to maintain a reliable output.","correct":true,"id":"H"}],"answer":"Quality-critical checks should remain proportionate to the risk. A reduced check is not automatically equivalent and needs explicit evaluation when time changes. A realistic adjustment may be needed to maintain a reliable output. A truthful account distinguishes adaptation from an unchanged delivery. Evidence and approved handling remain necessary during a minor disruption.","source":{"anchor":"ksb-b2","guideSha256":"6e744782cad76d417e14895ea2bdf8e6444638390cf404222d7b43216032bd60","excerpt":"Describe a minor unexpected change, your initiative, the options considered and the adjustment you made within your responsibility."},"id":"T42-E2-Q01"},{"ksb":"B2","objective":"Reflecting on adjustment","prompt":"A temporary tool constraint led you to use an approved alternative and still meet the key requirement. Which account demonstrates B2?","options":[{"text":"Describe the observed effect on quality and productivity","why":"Outcome claims need genuine observation or clearly stated estimation.","correct":true,"id":"A"},{"text":"Explain what you would reuse or improve next time","why":"Reflection should remain truthful about learning and contribution.","correct":true,"id":"B"},{"text":"Claim exact time savings without any supporting basis","why":"Outcome claims need genuine observation or clearly stated estimation.","correct":false,"id":"C"},{"text":"Explain the alternatives, chosen adjustment and checks","why":"A reasoned account connects the action to the constraint and outcome.","correct":true,"id":"D"},{"text":"Describe adaptability only as a personality trait","why":"The behaviour is better demonstrated through an actual situation and response.","correct":false,"id":"E"},{"text":"Describe the specific unexpected constraint","why":"The behaviour is better demonstrated through an actual situation and response.","correct":true,"id":"F"},{"text":"Attribute the whole team's recovery solely to yourself","why":"Reflection should remain truthful about learning and contribution.","correct":false,"id":"G"},{"text":"List button presses without explaining why the adjustment worked","why":"A reasoned account connects the action to the constraint and outcome.","correct":false,"id":"H"}],"answer":"The behaviour is better demonstrated through an actual situation and response. A reasoned account connects the action to the constraint and outcome. Outcome claims need genuine observation or clearly stated estimation. Reflection should remain truthful about learning and contribution.","source":{"anchor":"ksb-b2","guideSha256":"6e744782cad76d417e14895ea2bdf8e6444638390cf404222d7b43216032bd60","excerpt":"Describe a minor unexpected change, your initiative, the options considered and the adjustment you made within your responsibility."},"id":"T42-E2-Q02"},{"ksb":"B2","objective":"Slight delay in source","prompt":"A routine file arrives late, but independent documentation and chart explanations can be completed meanwhile. Which actions show productive adaptation?","options":[{"text":"Skip reconciliation automatically to recover the delay","why":"Time pressure does not justify silently abandoning important checks.","correct":false,"id":"A"},{"text":"Retain essential validation when the file arrives","why":"Time pressure does not justify silently abandoning important checks.","correct":true,"id":"B"},{"text":"Reorder useful tasks that do not depend on the file","why":"Adjusting the sequence can preserve productivity while the dependency is unresolved.","correct":true,"id":"C"},{"text":"Wait without progressing any independent work","why":"Adjusting the sequence can preserve productivity while the dependency is unresolved.","correct":false,"id":"D"},{"text":"Describe the short operational delay as a complete organisational strategy change","why":"The response and explanation should match the actual scale and facts of the disruption.","correct":false,"id":"E"},{"text":"Check the revised arrival estimate and delivery impact","why":"Delivery needs to account for the remaining work and quality checks.","correct":true,"id":"F"},{"text":"Copy last week's values and label them as this week's actuals","why":"The response and explanation should match the actual scale and facts of the disruption.","correct":false,"id":"G"},{"text":"Promise the original timing without assessing the shortened validation window","why":"Delivery needs to account for the remaining work and quality checks.","correct":false,"id":"H"}],"answer":"Adjusting the sequence can preserve productivity while the dependency is unresolved. Delivery needs to account for the remaining work and quality checks. Time pressure does not justify silently abandoning important checks. The response and explanation should match the actual scale and facts of the disruption.","source":{"anchor":"ksb-b2","guideSha256":"6e744782cad76d417e14895ea2bdf8e6444638390cf404222d7b43216032bd60","excerpt":"Describe a minor unexpected change, your initiative, the options considered and the adjustment you made within your responsibility."},"id":"T42-E2-Q03"},{"ksb":"B2","objective":"Productive escalation","prompt":"A minor access problem blocks one part of your task, and you cannot change permissions yourself. Which behaviour is appropriate?","options":[{"text":"Explain the dependency and likely effect on delivery","why":"Early communication supports realistic coordination.","correct":true,"id":"A"},{"text":"Mark the task complete when the request is acknowledged","why":"Acknowledgement does not establish that the required operation now works.","correct":false,"id":"B"},{"text":"Raise a focused request with the responsible team","why":"The issue should be addressed within the relevant authority and controls.","correct":true,"id":"C"},{"text":"Recheck the blocked step once access is resolved","why":"Acknowledgement does not establish that the required operation now works.","correct":true,"id":"D"},{"text":"Attempt to grant yourself access through another account","why":"The issue should be addressed within the relevant authority and controls.","correct":false,"id":"E"},{"text":"Conceal the blocker until the deadline passes","why":"Early communication supports realistic coordination.","correct":false,"id":"F"},{"text":"Treat asking for help as evidence that you failed to work independently","why":"Appropriate support can be part of effective independent task management.","correct":false,"id":"G"},{"text":"Continue independent work where feasible","why":"Appropriate support can be part of effective independent task management.","correct":true,"id":"H"}],"answer":"The issue should be addressed within the relevant authority and controls. Appropriate support can be part of effective independent task management. Early communication supports realistic coordination. Acknowledgement does not establish that the required operation now works.","source":{"anchor":"ksb-b2","guideSha256":"6e744782cad76d417e14895ea2bdf8e6444638390cf404222d7b43216032bd60","excerpt":"Describe a minor unexpected change, your initiative, the options considered and the adjustment you made within your responsibility."},"id":"T42-E2-Q04"},{"ksb":"B2","objective":"Substitute source","prompt":"A small reference file is temporarily inaccessible. An approved cached version exists but may be older. Which decision process is justified?","options":[{"text":"Assume a previously used file guarantees today's join is correct","why":"Current inputs can introduce different keys or relationships.","correct":false,"id":"A"},{"text":"Validate the resulting matches and totals","why":"Current inputs can introduce different keys or relationships.","correct":true,"id":"B"},{"text":"Check whether its currency and definitions meet the task","why":"Matching structure does not establish current values or suitability; assess age, content and the decision's tolerance before using the substitute.","correct":true,"id":"C"},{"text":"Escalate if the essential requirement cannot be met","why":"Adaptability includes recognising when an alternative is unsuitable.","correct":true,"id":"D"},{"text":"Accept the cached reference because its column names match the current specification","why":"Matching structure does not establish current values or suitability; assess age, content and the decision's tolerance before using the substitute.","correct":false,"id":"E"},{"text":"Treat any available file as a sufficient replacement","why":"Adaptability includes recognising when an alternative is unsuitable.","correct":false,"id":"F"},{"text":"Present the older snapshot as newly collected information","why":"Stakeholders need an accurate account of the substitute's period and limitations.","correct":false,"id":"G"},{"text":"Explain any limitation and obtain relevant agreement","why":"Stakeholders need an accurate account of the substitute's period and limitations.","correct":true,"id":"H"}],"answer":"Matching structure does not establish current values or suitability; assess age, content and the decision's tolerance before using the substitute. Stakeholders need an accurate account of the substitute's period and limitations. Current inputs can introduce different keys or relationships. Adaptability includes recognising when an alternative is unsuitable.","source":{"anchor":"ksb-b2","guideSha256":"6e744782cad76d417e14895ea2bdf8e6444638390cf404222d7b43216032bd60","excerpt":"Describe a minor unexpected change, your initiative, the options considered and the adjustment you made within your responsibility."},"id":"T42-E2-Q05"},{"ksb":"B2","objective":"Tool unavailable","prompt":"An approved charting tool is briefly unavailable before a meeting. You can produce a checked table in another approved tool. Which response is appropriate?","options":[{"text":"Confirm the table can communicate the required finding","why":"The alternative should meet the decision need within handling constraints.","correct":true,"id":"A"},{"text":"Recheck the exported values and definitions","why":"A new representation can introduce issues that need checking.","correct":true,"id":"B"},{"text":"Use an unapproved service solely to preserve the original styling","why":"The alternative should meet the decision need within handling constraints.","correct":false,"id":"C"},{"text":"Present the table as though every planned interaction is available","why":"Stakeholders should know what the alternative can and cannot do.","correct":false,"id":"D"},{"text":"Assume changing tools cannot alter formatting or interpretation","why":"A new representation can introduce issues that need checking.","correct":false,"id":"E"},{"text":"Preserve a practical plan for later restoration if needed","why":"A proportionate response addresses the immediate disruption and actual future need.","correct":true,"id":"F"},{"text":"Explain the temporary change in presentation","why":"Stakeholders should know what the alternative can and cannot do.","correct":true,"id":"G"},{"text":"Rebuild the whole project unnecessarily without considering the brief outage","why":"A proportionate response addresses the immediate disruption and actual future need.","correct":false,"id":"H"}],"answer":"The alternative should meet the decision need within handling constraints. Stakeholders should know what the alternative can and cannot do. A new representation can introduce issues that need checking. A proportionate response addresses the immediate disruption and actual future need.","source":{"anchor":"ksb-b2","guideSha256":"6e744782cad76d417e14895ea2bdf8e6444638390cf404222d7b43216032bd60","excerpt":"Describe a minor unexpected change, your initiative, the options considered and the adjustment you made within your responsibility."},"id":"T42-E2-Q06"},{"ksb":"B2","objective":"Last-minute clarification","prompt":"A stakeholder clarifies a label shortly before delivery without changing the underlying measure. Which adaptation is appropriate?","options":[{"text":"Add unrelated features to demonstrate flexibility","why":"The account and response should remain proportionate to the actual clarification.","correct":false,"id":"A"},{"text":"Claim a major scope pivot occurred when only wording changed","why":"The account and response should remain proportionate to the actual clarification.","correct":false,"id":"B"},{"text":"Check the delivered view and exported material","why":"Presentation changes still need an appropriate interpretation check.","correct":true,"id":"C"},{"text":"Update only the title while leaving contradictory exports","why":"Consistent communication prevents the same measure being described differently across outputs.","correct":false,"id":"D"},{"text":"Change the calculation to match a guessed interpretation","why":"A wording clarification should not silently change the measure.","correct":false,"id":"E"},{"text":"Confirm the intended meaning of the revised label","why":"A wording clarification should not silently change the measure.","correct":true,"id":"F"},{"text":"Assume a text-only edit cannot introduce confusion","why":"Presentation changes still need an appropriate interpretation check.","correct":false,"id":"G"},{"text":"Update relevant labels and explanations consistently","why":"Consistent communication prevents the same measure being described differently across outputs.","correct":true,"id":"H"}],"answer":"A wording clarification should not silently change the measure. Consistent communication prevents the same measure being described differently across outputs. Presentation changes still need an appropriate interpretation check. The account and response should remain proportionate to the actual clarification.","source":{"anchor":"ksb-b2","guideSha256":"6e744782cad76d417e14895ea2bdf8e6444638390cf404222d7b43216032bd60","excerpt":"Describe a minor unexpected change, your initiative, the options considered and the adjustment you made within your responsibility."},"id":"T42-E2-Q07"},{"ksb":"B2","objective":"Small output adjustment","prompt":"A meeting room cannot display your interactive report, but a static export is permitted. Which response preserves the purpose?","options":[{"text":"Use an unauthorised public link to restore convenience","why":"The alternative should be described honestly and remain within approved access arrangements.","correct":false,"id":"A"},{"text":"Depend on hover text that the export cannot show","why":"Static material needs context that would otherwise be interactive.","correct":false,"id":"B"},{"text":"Claim the static export still supports interactive drill-through","why":"The alternative should be described honestly and remain within approved access arrangements.","correct":false,"id":"C"},{"text":"Select views that answer the meeting's key question","why":"A useful static alternative should be relevant and appropriately controlled.","correct":true,"id":"D"},{"text":"Include essential filters, units and limitations","why":"Static material needs context that would otherwise be interactive.","correct":true,"id":"E"},{"text":"Assume a desktop preview guarantees room readability","why":"Display conditions can affect whether the audience can use the output.","correct":false,"id":"F"},{"text":"Check readability on the available display","why":"Display conditions can affect whether the audience can use the output.","correct":true,"id":"G"},{"text":"Export every hidden tab indiscriminately","why":"A useful static alternative should be relevant and appropriately controlled.","correct":false,"id":"H"}],"answer":"A useful static alternative should be relevant and appropriately controlled. Static material needs context that would otherwise be interactive. Display conditions can affect whether the audience can use the output. The alternative should be described honestly and remain within approved access arrangements.","source":{"anchor":"ksb-b2","guideSha256":"6e744782cad76d417e14895ea2bdf8e6444638390cf404222d7b43216032bd60","excerpt":"Describe a minor unexpected change, your initiative, the options considered and the adjustment you made within your responsibility."},"id":"T42-E2-Q08"},{"ksb":"B2","objective":"Optional field missing","prompt":"A scheduled extract lacks a nonessential breakdown field, while the agreed core measure remains available. Which adaptation is justified?","options":[{"text":"Validate the adjusted output and explain its limit","why":"The visible output should match the actual available analysis.","correct":true,"id":"A"},{"text":"Substitute a similarly named field without checking meaning","why":"A substitute needs semantic validation, and the account should describe the adjusted delivery honestly.","correct":false,"id":"B"},{"text":"Retain the breakdown label while removing its filter logic","why":"The visible output should match the actual available analysis.","correct":false,"id":"C"},{"text":"Assume the entire project must stop without examining impact","why":"A missing optional field may permit a useful qualified delivery.","correct":false,"id":"D"},{"text":"Claim the original breakdown was fully delivered","why":"A substitute needs semantic validation, and the account should describe the adjusted delivery honestly.","correct":false,"id":"E"},{"text":"Assess the effect on the requested breakdown and core output","why":"A missing optional field may permit a useful qualified delivery.","correct":true,"id":"F"},{"text":"Invent values to keep the original chart layout","why":"Fabrication does not resolve missing information.","correct":false,"id":"G"},{"text":"Agree omission or an approved alternative with the stakeholder","why":"Fabrication does not resolve missing information.","correct":true,"id":"H"}],"answer":"A missing optional field may permit a useful qualified delivery. Fabrication does not resolve missing information. The visible output should match the actual available analysis. A substitute needs semantic validation, and the account should describe the adjusted delivery honestly.","source":{"anchor":"ksb-b2","guideSha256":"6e744782cad76d417e14895ea2bdf8e6444638390cf404222d7b43216032bd60","excerpt":"Describe a minor unexpected change, your initiative, the options considered and the adjustment you made within your responsibility."},"id":"T42-E2-Q09"},{"ksb":"B2","objective":"Minor schema change","prompt":"A supplier renames a column but confirms its meaning and values are unchanged. Which response is proportionate?","options":[{"text":"Re-plan every unrelated project activity automatically","why":"A minor change calls for an impact-based response rather than unnecessary broad disruption.","correct":false,"id":"A"},{"text":"Record the change for repeatable future refreshes","why":"A recorded mapping supports a reliable recurring workflow.","correct":true,"id":"B"},{"text":"Update the mapping through the normal change process","why":"Confirmed semantic continuity supports a targeted mapping change.","correct":true,"id":"C"},{"text":"Treat the new name as an entirely unrelated measure without checking","why":"Confirmed semantic continuity supports a targeted mapping change.","correct":false,"id":"D"},{"text":"Assume a rename cannot break any downstream calculation","why":"Name-based dependencies can fail even when values have not changed.","correct":false,"id":"E"},{"text":"Test the affected transformation and result","why":"Name-based dependencies can fail even when values have not changed.","correct":true,"id":"F"},{"text":"Communicate any practical impact to affected users","why":"A minor change calls for an impact-based response rather than unnecessary broad disruption.","correct":true,"id":"G"},{"text":"Make an undocumented manual adjustment each time","why":"A recorded mapping supports a reliable recurring workflow.","correct":false,"id":"H"}],"answer":"Confirmed semantic continuity supports a targeted mapping change. Name-based dependencies can fail even when values have not changed. A recorded mapping supports a reliable recurring workflow. A minor change calls for an impact-based response rather than unnecessary broad disruption.","source":{"anchor":"ksb-b2","guideSha256":"6e744782cad76d417e14895ea2bdf8e6444638390cf404222d7b43216032bd60","excerpt":"Describe a minor unexpected change, your initiative, the options considered and the adjustment you made within your responsibility."},"id":"T42-E2-Q10"}]},{"id":"T43","title":"B3 · Independent & Collaborative Working","description":"Independent contribution, coordination and effects on others.","questions":[{"ksb":"B3","objective":"Team outcome attribution","prompt":"A team project succeeds, and your contribution was building and validating a comparison. Which account is accurate?","options":[{"text":"Describe the comparison and checks you personally performed","why":"Your contribution should be distinct from the wider outcome.","correct":true,"id":"A"},{"text":"Invent praise to demonstrate positive impact","why":"Impact evidence must remain truthful.","correct":false,"id":"B"},{"text":"Describe only the team's success without your role","why":"The account needs both your work and its connection to the shared result.","correct":false,"id":"C"},{"text":"Treat being copied into messages as proof you completed the related work","why":"Participation and visibility do not establish personal execution or ownership.","correct":false,"id":"D"},{"text":"Claim every meeting decision was your independent decision","why":"Participation and visibility do not establish personal execution or ownership.","correct":false,"id":"E"},{"text":"Attribute the entire team's delivery to yourself","why":"Your contribution should be distinct from the wider outcome.","correct":false,"id":"F"},{"text":"Explain how your output supported colleagues' next actions","why":"The account needs both your work and its connection to the shared result.","correct":true,"id":"G"},{"text":"Reference genuine feedback or observations of its usefulness","why":"Impact evidence must remain truthful.","correct":true,"id":"H"}],"answer":"Your contribution should be distinct from the wider outcome. The account needs both your work and its connection to the shared result. Impact evidence must remain truthful. Participation and visibility do not establish personal execution or ownership.","source":{"anchor":"ksb-b3","guideSha256":"ed7a422a0cad1868dc9d98971b13d412dba7ea1d5b5578a0c8dd2a7a5f18c359","excerpt":"Explain how you organised and delivered your own responsibilities, recognised when others' expertise mattered and coordinated dependencies."},"id":"T43-E2-Q01"},{"ksb":"B3","objective":"Working across boundaries","prompt":"A project depends on another team's data, but they have competing deadlines. Which behaviour is constructive?","options":[{"text":"Explore a feasible agreed sequence or reduced interim input","why":"Collaboration can identify a proportionate option within authority and capacity.","correct":true,"id":"A"},{"text":"Send an urgent request with no explanation of scope","why":"A focused request helps others assess and prioritise the dependency.","correct":false,"id":"B"},{"text":"Demand unrestricted access as the only acceptable solution","why":"Collaboration can identify a proportionate option within authority and capacity.","correct":false,"id":"C"},{"text":"Communicate the agreed dependency to your own stakeholders","why":"Honest coordination reflects the actual remaining dependency.","correct":true,"id":"D"},{"text":"Clarify the specific need, timing and impact","why":"A focused request helps others assess and prioritise the dependency.","correct":true,"id":"E"},{"text":"Assume your deadline overrides every other team's responsibility","why":"Effective collaboration respects both priorities and truthful attribution.","correct":false,"id":"F"},{"text":"Report the other team's work as your own initiative","why":"Effective collaboration respects both priorities and truthful attribution.","correct":false,"id":"G"},{"text":"Promise delivery as though the other team's work were already complete","why":"Honest coordination reflects the actual remaining dependency.","correct":false,"id":"H"}],"answer":"A focused request helps others assess and prioritise the dependency. Collaboration can identify a proportionate option within authority and capacity. Honest coordination reflects the actual remaining dependency. Effective collaboration respects both priorities and truthful attribution.","source":{"anchor":"ksb-b3","guideSha256":"ed7a422a0cad1868dc9d98971b13d412dba7ea1d5b5578a0c8dd2a7a5f18c359","excerpt":"Explain how you organised and delivered your own responsibilities, recognised when others' expertise mattered and coordinated dependencies."},"id":"T43-E2-Q02"},{"ksb":"B3","objective":"Coordinating delivery","prompt":"Two people need to edit related parts of a recurring report. Which arrangements support effective teamwork?","options":[{"text":"Agree responsibilities and how changes will be reviewed","why":"Clear ownership and review reduce accidental conflicts.","correct":true,"id":"A"},{"text":"Communicate changes affecting the other person's calculations","why":"Explicit communication helps maintain consistent interpretation across components.","correct":true,"id":"B"},{"text":"Keep a suitable record of agreed decisions","why":"Shared decisions should be available to the people whose work depends on them.","correct":true,"id":"C"},{"text":"Assume a changed definition will be noticed automatically","why":"Explicit communication helps maintain consistent interpretation across components.","correct":false,"id":"D"},{"text":"Check the combined output after integration","why":"Combined behaviour can reveal errors absent from isolated components.","correct":true,"id":"E"},{"text":"Let both overwrite shared files without coordination","why":"Clear ownership and review reduce accidental conflicts.","correct":false,"id":"F"},{"text":"Validate each piece separately and assume integration cannot introduce issues","why":"Combined behaviour can reveal errors absent from isolated components.","correct":false,"id":"G"},{"text":"Rely on undocumented private assumptions","why":"Shared decisions should be available to the people whose work depends on them.","correct":false,"id":"H"}],"answer":"Clear ownership and review reduce accidental conflicts. Explicit communication helps maintain consistent interpretation across components. Shared decisions should be available to the people whose work depends on them. Combined behaviour can reveal errors absent from isolated components.","source":{"anchor":"ksb-b3","guideSha256":"ed7a422a0cad1868dc9d98971b13d412dba7ea1d5b5578a0c8dd2a7a5f18c359","excerpt":"Explain how you organised and delivered your own responsibilities, recognised when others' expertise mattered and coordinated dependencies."},"id":"T43-E2-Q03"},{"ksb":"B3","objective":"Conflicting team needs","prompt":"Your colleague needs a stable dataset early, while you are still investigating an optional field. Which collaboration is constructive?","options":[{"text":"Claim the draft was final to avoid a difficult discussion","why":"Honest status helps the team make appropriate decisions.","correct":false,"id":"A"},{"text":"Continue your investigation and share relevant findings","why":"A shared dependency can require follow-up when findings or assumptions change.","correct":true,"id":"B"},{"text":"Explain the trade-off and actual effect on the colleague","why":"Honest status helps the team make appropriate decisions.","correct":true,"id":"C"},{"text":"Treat handing over a draft as ending all responsibility","why":"A shared dependency can require follow-up when findings or assumptions change.","correct":false,"id":"D"},{"text":"Delay every input without explaining which part is uncertain","why":"A bounded release can support others if its limits and suitability are agreed.","correct":false,"id":"E"},{"text":"Agree a usable version and clearly identify the unresolved field","why":"A bounded release can support others if its limits and suitability are agreed.","correct":true,"id":"F"},{"text":"Change the schema silently after handover","why":"Unexpected changes can disrupt downstream work.","correct":false,"id":"G"},{"text":"Coordinate changes so the colleague can manage dependencies","why":"Unexpected changes can disrupt downstream work.","correct":true,"id":"H"}],"answer":"A bounded release can support others if its limits and suitability are agreed. Unexpected changes can disrupt downstream work. A shared dependency can require follow-up when findings or assumptions change. Honest status helps the team make appropriate decisions.","source":{"anchor":"ksb-b3","guideSha256":"ed7a422a0cad1868dc9d98971b13d412dba7ea1d5b5578a0c8dd2a7a5f18c359","excerpt":"Explain how you organised and delivered your own responsibilities, recognised when others' expertise mattered and coordinated dependencies."},"id":"T43-E2-Q04"},{"ksb":"B3","objective":"Positive impact evidence","prompt":"You say your work made a colleague's task easier. Which supporting detail is strongest?","options":[{"text":"Describe the specific task or confusion your output addressed","why":"A concrete effect is more informative than a general self-description.","correct":true,"id":"A"},{"text":"State only that you are a helpful team member","why":"A concrete effect is more informative than a general self-description.","correct":false,"id":"B"},{"text":"Present an unmeasured exact percentage improvement as verified","why":"Quantified claims need an appropriate basis.","correct":false,"id":"C"},{"text":"Assume a downloaded file was used successfully","why":"Activity and download records alone do not establish a positive practical outcome.","correct":false,"id":"D"},{"text":"Use genuine feedback or an observed change in the workflow","why":"Quantified claims need an appropriate basis.","correct":true,"id":"E"},{"text":"Claim sole credit for changes dependent on several people","why":"Impact should be attributed accurately within the shared work.","correct":false,"id":"F"},{"text":"Explain your contribution and the conditions that enabled the benefit","why":"Impact should be attributed accurately within the shared work.","correct":true,"id":"G"},{"text":"Count attendance at unrelated meetings as proof of benefit","why":"Activity and download records alone do not establish a positive practical outcome.","correct":false,"id":"H"}],"answer":"A concrete effect is more informative than a general self-description. Quantified claims need an appropriate basis. Impact should be attributed accurately within the shared work. Activity and download records alone do not establish a positive practical outcome.","source":{"anchor":"ksb-b3","guideSha256":"ed7a422a0cad1868dc9d98971b13d412dba7ea1d5b5578a0c8dd2a7a5f18c359","excerpt":"Explain how you organised and delivered your own responsibilities, recognised when others' expertise mattered and coordinated dependencies."},"id":"T43-E2-Q05"},{"ksb":"B3","objective":"Appropriate initiative","prompt":"You notice an unexplained discrepancy within your assigned analysis. Which response demonstrates independent working with suitable collaboration?","options":[{"text":"Change source records unilaterally to make your total match","why":"A boundary in authority calls for collaboration rather than an unauthorised correction.","correct":false,"id":"A"},{"text":"Ignore the discrepancy until someone explicitly instructs you to investigate","why":"Taking appropriate initiative can help resolve a problem before it affects delivery.","correct":false,"id":"B"},{"text":"Explain your reasoning and findings to affected colleagues","why":"Shared reasoning helps others understand the issue and its consequences.","correct":true,"id":"C"},{"text":"Record agreed actions and responsibility","why":"Coordination needs follow-through and verification, not just an initial contact.","correct":true,"id":"D"},{"text":"Involve the source owner if the cause concerns their system","why":"A boundary in authority calls for collaboration rather than an unauthorised correction.","correct":true,"id":"E"},{"text":"Send only an unexplained corrected number","why":"Shared reasoning helps others understand the issue and its consequences.","correct":false,"id":"F"},{"text":"Treat the first informal conversation as proof the issue is fully resolved","why":"Coordination needs follow-through and verification, not just an initial contact.","correct":false,"id":"G"},{"text":"Carry out relevant checks within your responsibility","why":"Taking appropriate initiative can help resolve a problem before it affects delivery.","correct":true,"id":"H"}],"answer":"Taking appropriate initiative can help resolve a problem before it affects delivery. A boundary in authority calls for collaboration rather than an unauthorised correction. Shared reasoning helps others understand the issue and its consequences. Coordination needs follow-through and verification, not just an initial contact.","source":{"anchor":"ksb-b3","guideSha256":"ed7a422a0cad1868dc9d98971b13d412dba7ea1d5b5578a0c8dd2a7a5f18c359","excerpt":"Explain how you organised and delivered your own responsibilities, recognised when others' expertise mattered and coordinated dependencies."},"id":"T43-E2-Q06"},{"ksb":"B3","objective":"Professional disagreement","prompt":"You and a colleague propose different definitions for a metric. Which approach supports independent reasoning and collaboration?","options":[{"text":"Compare both definitions against the agreed requirement","why":"A favourable output is not a sufficient reason to select a definition.","correct":true,"id":"A"},{"text":"Defend your first choice regardless of new information","why":"Independent judgement can be revised when better evidence emerges.","correct":false,"id":"B"},{"text":"Accept or reject the alternative solely by seniority","why":"A useful discussion considers the substantive meaning and decision need.","correct":false,"id":"C"},{"text":"Explain your rationale and evidence","why":"A useful discussion considers the substantive meaning and decision need.","correct":true,"id":"D"},{"text":"Agree and record the resolved approach with appropriate stakeholders","why":"Shared understanding reduces conflicting interpretations.","correct":true,"id":"E"},{"text":"Maintain inconsistent definitions silently in separate outputs","why":"Shared understanding reduces conflicting interpretations.","correct":false,"id":"F"},{"text":"Choose whichever produces the preferred ranking","why":"A favourable output is not a sufficient reason to select a definition.","correct":false,"id":"G"},{"text":"Acknowledge valid evidence that changes your view","why":"Independent judgement can be revised when better evidence emerges.","correct":true,"id":"H"}],"answer":"A useful discussion considers the substantive meaning and decision need. A favourable output is not a sufficient reason to select a definition. Shared understanding reduces conflicting interpretations. Independent judgement can be revised when better evidence emerges.","source":{"anchor":"ksb-b3","guideSha256":"ed7a422a0cad1868dc9d98971b13d412dba7ea1d5b5578a0c8dd2a7a5f18c359","excerpt":"Explain how you organised and delivered your own responsibilities, recognised when others' expertise mattered and coordinated dependencies."},"id":"T43-E2-Q07"},{"ksb":"B3","objective":"Owning a workstream","prompt":"You own the analysis while a colleague owns the source extraction. Which working approach balances independence and collaboration?","options":[{"text":"Plan your analysis tasks and dependencies","why":"Appropriate initiative supports independent responsibility.","correct":true,"id":"A"},{"text":"Agree the input definition and delivery with the colleague","why":"Coordinating dependencies helps the combined work succeed.","correct":true,"id":"B"},{"text":"Claim the extraction as your own because your report used it","why":"A truthful account distinguishes your work from others' contributions.","correct":false,"id":"C"},{"text":"Make decisions within your remit and seek input where needed","why":"Collaboration should respect responsibilities rather than bypass them.","correct":true,"id":"D"},{"text":"Explain each person's contribution accurately","why":"A truthful account distinguishes your work from others' contributions.","correct":true,"id":"E"},{"text":"Wait for detailed instructions on every routine decision","why":"Appropriate initiative supports independent responsibility.","correct":false,"id":"F"},{"text":"Treat collaboration as permission to change the source without its owner","why":"Collaboration should respect responsibilities rather than bypass them.","correct":false,"id":"G"},{"text":"Ignore the extraction dependency because it is someone else's task","why":"Coordinating dependencies helps the combined work succeed.","correct":false,"id":"H"}],"answer":"Appropriate initiative supports independent responsibility. Coordinating dependencies helps the combined work succeed. Collaboration should respect responsibilities rather than bypass them. A truthful account distinguishes your work from others' contributions.","source":{"anchor":"ksb-b3","guideSha256":"ed7a422a0cad1868dc9d98971b13d412dba7ea1d5b5578a0c8dd2a7a5f18c359","excerpt":"Explain how you organised and delivered your own responsibilities, recognised when others' expertise mattered and coordinated dependencies."},"id":"T43-E2-Q08"},{"ksb":"B3","objective":"Seeking expertise","prompt":"You are responsible for a statistical analysis but uncertain whether repeated observations violate the proposed method. Which behaviour is appropriate?","options":[{"text":"Apply and understand the agreed reasoning","why":"You still need to explain and apply the method appropriately in your project.","correct":true,"id":"A"},{"text":"Copy an expert's answer without understanding its assumptions","why":"You still need to explain and apply the method appropriately in your project.","correct":false,"id":"B"},{"text":"Investigate the design and formulate a focused question","why":"Independence does not require ignoring a material methodological uncertainty.","correct":true,"id":"C"},{"text":"Seek relevant statistical advice while retaining responsibility for your work","why":"Targeted expertise can support a specific gap without abandoning your role.","correct":true,"id":"D"},{"text":"Treat asking for advice as evidence no learning occurred","why":"Collaboration and learning can coexist with truthful attribution of contributions.","correct":false,"id":"E"},{"text":"Delegate every routine choice because one issue is uncertain","why":"Targeted expertise can support a specific gap without abandoning your role.","correct":false,"id":"F"},{"text":"Proceed without checking to appear fully independent","why":"Independence does not require ignoring a material methodological uncertainty.","correct":false,"id":"G"},{"text":"Claim the expert's analysis as entirely your own","why":"Collaboration and learning can coexist with truthful attribution of contributions.","correct":false,"id":"H"}],"answer":"Independence does not require ignoring a material methodological uncertainty. Targeted expertise can support a specific gap without abandoning your role. You still need to explain and apply the method appropriately in your project. Collaboration and learning can coexist with truthful attribution of contributions.","source":{"anchor":"ksb-b3","guideSha256":"ed7a422a0cad1868dc9d98971b13d412dba7ea1d5b5578a0c8dd2a7a5f18c359","excerpt":"Explain how you organised and delivered your own responsibilities, recognised when others' expertise mattered and coordinated dependencies."},"id":"T43-E2-Q09"},{"ksb":"B3","objective":"Useful handover","prompt":"Another analyst will reuse your preparation workflow. Which actions positively support their work?","options":[{"text":"Check that the recipient can follow the relevant process","why":"Feedback or practical review gives stronger evidence that the handover was useful.","correct":true,"id":"A"},{"text":"Provide only the final chart","why":"Reuse requires understanding of how the result was produced.","correct":false,"id":"B"},{"text":"Claim reduced workload without any observation or feedback","why":"Volume and unsupported assertions do not establish the effect on the colleague.","correct":false,"id":"C"},{"text":"Measure positive impact only by document length","why":"Volume and unsupported assertions do not establish the effect on the colleague.","correct":false,"id":"D"},{"text":"Document inputs, assumptions and important steps","why":"Reuse requires understanding of how the result was produced.","correct":true,"id":"E"},{"text":"Hide limitations to make the handover look complete","why":"Known limitations help the recipient use and maintain the workflow responsibly.","correct":false,"id":"F"},{"text":"Explain known exceptions and checks","why":"Known limitations help the recipient use and maintain the workflow responsibly.","correct":true,"id":"G"},{"text":"Infer understanding solely from sending a file","why":"Feedback or practical review gives stronger evidence that the handover was useful.","correct":false,"id":"H"}],"answer":"Reuse requires understanding of how the result was produced. Known limitations help the recipient use and maintain the workflow responsibly. Feedback or practical review gives stronger evidence that the handover was useful. Volume and unsupported assertions do not establish the effect on the colleague.","source":{"anchor":"ksb-b3","guideSha256":"ed7a422a0cad1868dc9d98971b13d412dba7ea1d5b5578a0c8dd2a7a5f18c359","excerpt":"Explain how you organised and delivered your own responsibilities, recognised when others' expertise mattered and coordinated dependencies."},"id":"T43-E2-Q10"}]},{"id":"T44","title":"B4 · Logical & Analytical Thinking","description":"Reasoned investigation, independent choices and evidence-led judgement.","questions":[{"ksb":"B4","objective":"Visual reasoning","prompt":"A chart makes a small difference look dramatic because of its scale. Which evaluation is justified?","options":[{"text":"Hide axis labels to avoid questions about the effect","why":"Clear context helps users assess magnitude rather than rely on an impression.","correct":false,"id":"A"},{"text":"Compare the visual impression with the actual values","why":"The representation should support accurate interpretation of the data.","correct":true,"id":"B"},{"text":"Explain the scale choice and its consequences","why":"Clear context helps users assess magnitude rather than rely on an impression.","correct":true,"id":"C"},{"text":"Assume every chart produced by a standard tool is appropriately designed","why":"Tool defaults and visual prominence do not establish analytical meaning.","correct":false,"id":"D"},{"text":"Treat a striking image as stronger evidence than the numbers","why":"The representation should support accurate interpretation of the data.","correct":false,"id":"E"},{"text":"Switch to a line chart with the same compressed axis and assume the exaggeration is resolved","why":"Evaluate how the alternative represents actual magnitude and the comparison task; changing chart type alone may preserve the misleading scale effect.","correct":false,"id":"F"},{"text":"Consider a suitable alternative representation","why":"Evaluate how the alternative represents actual magnitude and the comparison task; changing chart type alone may preserve the misleading scale effect.","correct":true,"id":"G"},{"text":"Infer practical importance from apparent bar height alone","why":"Tool defaults and visual prominence do not establish analytical meaning.","correct":false,"id":"H"}],"answer":"The representation should support accurate interpretation of the data. Evaluate how the alternative represents actual magnitude and the comparison task; changing chart type alone may preserve the misleading scale effect. Clear context helps users assess magnitude rather than rely on an impression. Tool defaults and visual prominence do not establish analytical meaning.","source":{"anchor":"ksb-b4","guideSha256":"19544c61d4657ced69a0de9a91c60998a3caac5acfd7f29fa94d863d5f1dfbb2","excerpt":"Show how you independently structured an uncertain problem, formed explanations, chose tests and revised your judgement from evidence."},"id":"T44-E2-Q01"},{"ksb":"B4","objective":"Unexpected total","prompt":"A report total rises after a new join is added. Which investigation demonstrates logical reasoning?","options":[{"text":"Document the reasoning and remaining uncertainty","why":"Analytical judgement should reflect the strength and limits of the evidence.","correct":true,"id":"A"},{"text":"Inspect key multiplicity and unmatched records","why":"Execution success does not establish the intended relationship or coverage.","correct":true,"id":"B"},{"text":"Compare row counts before and after the join","why":"Checks should target the transformation associated with the change.","correct":true,"id":"C"},{"text":"Report a confident cause solely because it fits your first guess","why":"Analytical judgement should reflect the strength and limits of the evidence.","correct":false,"id":"D"},{"text":"Compare results under a verified correction","why":"A supported conclusion needs evidence that distinguishes the suspected cause.","correct":true,"id":"E"},{"text":"Assume a successful query proves the matching logic is correct","why":"Execution success does not establish the intended relationship or coverage.","correct":false,"id":"F"},{"text":"Accept the first plausible explanation without testing it","why":"A supported conclusion needs evidence that distinguishes the suspected cause.","correct":false,"id":"G"},{"text":"Start changing unrelated chart settings until the total looks familiar","why":"Checks should target the transformation associated with the change.","correct":false,"id":"H"}],"answer":"Checks should target the transformation associated with the change. Execution success does not establish the intended relationship or coverage. A supported conclusion needs evidence that distinguishes the suspected cause. Analytical judgement should reflect the strength and limits of the evidence.","source":{"anchor":"ksb-b4","guideSha256":"19544c61d4657ced69a0de9a91c60998a3caac5acfd7f29fa94d863d5f1dfbb2","excerpt":"Show how you independently structured an uncertain problem, formed explanations, chose tests and revised your judgement from evidence."},"id":"T44-E2-Q02"},{"ksb":"B4","objective":"Independent judgement","prompt":"A template instructs you to remove outliers, but a rare long-duration case may be genuine. Which response demonstrates analytical thinking?","options":[{"text":"Explain the effect of retaining or excluding the case","why":"Sensitivity should inform a justified decision, not optimise a preferred headline.","correct":true,"id":"A"},{"text":"Investigate the case before applying the rule","why":"A procedure needs interpretation in light of the actual data and purpose.","correct":true,"id":"B"},{"text":"Follow the template blindly despite relevant contrary context","why":"A procedure needs interpretation in light of the actual data and purpose.","correct":false,"id":"C"},{"text":"Choose whichever treatment produces the desired average","why":"Sensitivity should inform a justified decision, not optimise a preferred headline.","correct":false,"id":"D"},{"text":"Apply an authorised, documented treatment","why":"A transformation should be justified and traceable rather than silently invented.","correct":true,"id":"E"},{"text":"Claim the template eliminates the need for judgement","why":"A generic rule does not settle every context-specific analytical decision.","correct":false,"id":"F"},{"text":"Explain any limitation in the final interpretation","why":"A generic rule does not settle every context-specific analytical decision.","correct":true,"id":"G"},{"text":"Quietly change the value to a typical duration","why":"A transformation should be justified and traceable rather than silently invented.","correct":false,"id":"H"}],"answer":"A procedure needs interpretation in light of the actual data and purpose. Sensitivity should inform a justified decision, not optimise a preferred headline. A transformation should be justified and traceable rather than silently invented. A generic rule does not settle every context-specific analytical decision.","source":{"anchor":"ksb-b4","guideSha256":"19544c61d4657ced69a0de9a91c60998a3caac5acfd7f29fa94d863d5f1dfbb2","excerpt":"Show how you independently structured an uncertain problem, formed explanations, chose tests and revised your judgement from evidence."},"id":"T44-E2-Q03"},{"ksb":"B4","objective":"Evidence versus conjecture","prompt":"You suspect a source-system change caused missing values, but only timing coincidence is known. Which explanation is appropriate?","options":[{"text":"Collect only examples consistent with the preferred explanation","why":"A useful investigation should consider evidence that could challenge the hypothesis too.","correct":false,"id":"A"},{"text":"Present it as a hypothesis to investigate","why":"A temporal association alone does not prove the mechanism.","correct":true,"id":"B"},{"text":"Fill gaps in the account with plausible invented details","why":"Uncertainty should remain explicit rather than being replaced with fabricated evidence.","correct":false,"id":"C"},{"text":"State that no further evidence is needed because the story is coherent","why":"Coherence is not the same as empirical support.","correct":false,"id":"D"},{"text":"Seek logs, comparisons or reproduction that could test the hypothesis","why":"A useful investigation should consider evidence that could challenge the hypothesis too.","correct":true,"id":"E"},{"text":"Describe the coincidence as established causation","why":"A temporal association alone does not prove the mechanism.","correct":false,"id":"F"},{"text":"Explain what further check would strengthen or weaken the claim","why":"Coherence is not the same as empirical support.","correct":true,"id":"G"},{"text":"Distinguish verified findings from unresolved questions","why":"Uncertainty should remain explicit rather than being replaced with fabricated evidence.","correct":true,"id":"H"}],"answer":"A temporal association alone does not prove the mechanism. A useful investigation should consider evidence that could challenge the hypothesis too. Uncertainty should remain explicit rather than being replaced with fabricated evidence. Coherence is not the same as empirical support.","source":{"anchor":"ksb-b4","guideSha256":"19544c61d4657ced69a0de9a91c60998a3caac5acfd7f29fa94d863d5f1dfbb2","excerpt":"Show how you independently structured an uncertain problem, formed explanations, chose tests and revised your judgement from evidence."},"id":"T44-E2-Q04"},{"ksb":"B4","objective":"Contradictory evidence","prompt":"Your initial hypothesis blames duplicate rows, but the relevant keys are unique and filters differ between reports. Which response is logical?","options":[{"text":"Treat unique keys as proof every part of the report is correct","why":"Ruling out one cause does not validate the whole pipeline or automatically prove another.","correct":false,"id":"A"},{"text":"Claim the filter issue is proven before comparing the populations","why":"Ruling out one cause does not validate the whole pipeline or automatically prove another.","correct":false,"id":"B"},{"text":"Hide the abandoned hypothesis from the reasoning account","why":"A transparent account can show how evidence narrowed the explanation.","correct":false,"id":"C"},{"text":"Test whether filter differences explain the totals","why":"Inclusion rules can materially change numerical summaries.","correct":true,"id":"D"},{"text":"Record why the working explanation changed","why":"A transparent account can show how evidence narrowed the explanation.","correct":true,"id":"E"},{"text":"Ignore the filters because they are not numerical values","why":"Inclusion rules can materially change numerical summaries.","correct":false,"id":"F"},{"text":"Continue deleting rows because duplication was your first explanation","why":"Evidence against a hypothesis should change the investigation.","correct":false,"id":"G"},{"text":"Reconsider the duplicate-row hypothesis","why":"Evidence against a hypothesis should change the investigation.","correct":true,"id":"H"}],"answer":"Evidence against a hypothesis should change the investigation. Inclusion rules can materially change numerical summaries. A transparent account can show how evidence narrowed the explanation. Ruling out one cause does not validate the whole pipeline or automatically prove another.","source":{"anchor":"ksb-b4","guideSha256":"19544c61d4657ced69a0de9a91c60998a3caac5acfd7f29fa94d863d5f1dfbb2","excerpt":"Show how you independently structured an uncertain problem, formed explanations, chose tests and revised your judgement from evidence."},"id":"T44-E2-Q05"},{"ksb":"B4","objective":"Assumption visibility","prompt":"A comparison depends on treating two service definitions as equivalent. Which reasoning is appropriate?","options":[{"text":"Infer meaning solely from the preferred output","why":"Assumptions should be assessed using evidence, not desired results.","correct":false,"id":"A"},{"text":"Treat matching labels as proof of shared meaning","why":"Similar labels may hide different inclusion rules or definitions.","correct":false,"id":"B"},{"text":"Avoid sensitivity checks because they may complicate the story","why":"A sensitivity check can show whether the conclusion depends strongly on the assumption.","correct":false,"id":"C"},{"text":"Examine how a different reasonable mapping changes the conclusion","why":"A sensitivity check can show whether the conclusion depends strongly on the assumption.","correct":true,"id":"D"},{"text":"State limits if equivalence cannot be established","why":"The strength of the claim should match the available support.","correct":true,"id":"E"},{"text":"Make the equivalence assumption explicit","why":"Similar labels may hide different inclusion rules or definitions.","correct":true,"id":"F"},{"text":"Check the definitions with relevant sources or owners","why":"Assumptions should be assessed using evidence, not desired results.","correct":true,"id":"G"},{"text":"Present the comparison as exact despite unresolved meaning","why":"The strength of the claim should match the available support.","correct":false,"id":"H"}],"answer":"Similar labels may hide different inclusion rules or definitions. Assumptions should be assessed using evidence, not desired results. A sensitivity check can show whether the conclusion depends strongly on the assumption. The strength of the claim should match the available support.","source":{"anchor":"ksb-b4","guideSha256":"19544c61d4657ced69a0de9a91c60998a3caac5acfd7f29fa94d863d5f1dfbb2","excerpt":"Show how you independently structured an uncertain problem, formed explanations, chose tests and revised your judgement from evidence."},"id":"T44-E2-Q06"},{"ksb":"B4","objective":"Method selection","prompt":"A project asks about a difference between groups, but a colleague recommends a forecast because it is more advanced. Which reasoning is appropriate?","options":[{"text":"Choose a method that addresses the agreed question","why":"Complexity does not establish relevance to the analytical question.","correct":true,"id":"A"},{"text":"Check the data design and assumptions","why":"Data type alone does not establish sampling structure or assumptions.","correct":true,"id":"B"},{"text":"Explain a feasible alternative and its trade-offs","why":"A reasoned comparison supports an independent choice.","correct":true,"id":"C"},{"text":"State that the first suggested method must be correct","why":"A reasoned comparison supports an independent choice.","correct":false,"id":"D"},{"text":"Evaluate whether the result answers the original need","why":"An executed procedure may still fail to address the decision problem.","correct":true,"id":"E"},{"text":"Infer method suitability solely from numeric column types","why":"Data type alone does not establish sampling structure or assumptions.","correct":false,"id":"F"},{"text":"Judge success only by whether the software produced output","why":"An executed procedure may still fail to address the decision problem.","correct":false,"id":"G"},{"text":"Select the most complex available method regardless of purpose","why":"Complexity does not establish relevance to the analytical question.","correct":false,"id":"H"}],"answer":"Complexity does not establish relevance to the analytical question. Data type alone does not establish sampling structure or assumptions. A reasoned comparison supports an independent choice. An executed procedure may still fail to address the decision problem.","source":{"anchor":"ksb-b4","guideSha256":"19544c61d4657ced69a0de9a91c60998a3caac5acfd7f29fa94d863d5f1dfbb2","excerpt":"Show how you independently structured an uncertain problem, formed explanations, chose tests and revised your judgement from evidence."},"id":"T44-E2-Q07"},{"ksb":"B4","objective":"Competing explanations","prompt":"A monthly count falls. Possible explanations include real demand, a changed filter and an incomplete extract. Which approach is justified?","options":[{"text":"Treat a plausible narrative as equivalent to a verified cause","why":"Plausibility and magnitude alone do not establish the mechanism.","correct":false,"id":"A"},{"text":"Attribute the fall immediately to the preferred operational explanation","why":"Several plausible causes need investigation before a conclusion.","correct":false,"id":"B"},{"text":"Infer that the largest numerical change identifies the responsible process","why":"Plausibility and magnitude alone do not establish the mechanism.","correct":false,"id":"C"},{"text":"Update the explanation as evidence emerges","why":"Logical reasoning should respond to findings rather than protect an initial belief.","correct":true,"id":"D"},{"text":"Keep the original story despite contradictory records","why":"Logical reasoning should respond to findings rather than protect an initial belief.","correct":false,"id":"E"},{"text":"Check collection and transformation changes alongside operational context","why":"Several plausible causes need investigation before a conclusion.","correct":true,"id":"F"},{"text":"Use checks that distinguish the competing explanations","why":"Repeating an output does not necessarily test why it changed.","correct":true,"id":"G"},{"text":"Repeat the same summary without examining its inputs","why":"Repeating an output does not necessarily test why it changed.","correct":false,"id":"H"}],"answer":"Several plausible causes need investigation before a conclusion. Repeating an output does not necessarily test why it changed. Logical reasoning should respond to findings rather than protect an initial belief. Plausibility and magnitude alone do not establish the mechanism.","source":{"anchor":"ksb-b4","guideSha256":"19544c61d4657ced69a0de9a91c60998a3caac5acfd7f29fa94d863d5f1dfbb2","excerpt":"Show how you independently structured an uncertain problem, formed explanations, chose tests and revised your judgement from evidence."},"id":"T44-E2-Q08"},{"ksb":"B4","objective":"Evaluating a solution","prompt":"A revised transformation removes a discrepancy in one sample. Which reasoning supports deployment?","options":[{"text":"Assume one matching example proves universal correctness","why":"A sample success needs broader relevant validation.","correct":false,"id":"A"},{"text":"Compare important outputs and unintended effects","why":"A change can affect other measures or populations.","correct":true,"id":"B"},{"text":"Explain the result and remaining limits","why":"A bounded conclusion recognises what the checks actually establish.","correct":true,"id":"C"},{"text":"Consider maintenance and a feasible alternative","why":"Practical quality includes reliability and sustainment, not just coding effort.","correct":true,"id":"D"},{"text":"Check relevant cases and edge conditions beyond the demonstration","why":"A sample success needs broader relevant validation.","correct":true,"id":"E"},{"text":"Check only the originally visible symptom","why":"A change can affect other measures or populations.","correct":false,"id":"F"},{"text":"Choose solely by whichever fix took the least typing","why":"Practical quality includes reliability and sustainment, not just coding effort.","correct":false,"id":"G"},{"text":"Claim recurrence is impossible from one successful run","why":"A bounded conclusion recognises what the checks actually establish.","correct":false,"id":"H"}],"answer":"A sample success needs broader relevant validation. A change can affect other measures or populations. Practical quality includes reliability and sustainment, not just coding effort. A bounded conclusion recognises what the checks actually establish.","source":{"anchor":"ksb-b4","guideSha256":"19544c61d4657ced69a0de9a91c60998a3caac5acfd7f29fa94d863d5f1dfbb2","excerpt":"Show how you independently structured an uncertain problem, formed explanations, chose tests and revised your judgement from evidence."},"id":"T44-E2-Q09"},{"ksb":"B4","objective":"Prioritising checks","prompt":"A report has a large discrepancy after a known schema change. Which sequence is efficient and logical?","options":[{"text":"Compare a small reproducible example with expected behaviour","why":"A controlled example helps identify effects that simultaneous changes can obscure.","correct":true,"id":"A"},{"text":"Start with checks of the changed fields and dependencies","why":"Targeting a plausible change point can narrow the investigation efficiently.","correct":true,"id":"B"},{"text":"Inspect every unrelated visual element before the changed logic","why":"Targeting a plausible change point can narrow the investigation efficiently.","correct":false,"id":"C"},{"text":"Infer complete resolution from one convenient record alone","why":"A local demonstration needs appropriate broader validation.","correct":false,"id":"D"},{"text":"Modify many transformations simultaneously","why":"A controlled example helps identify effects that simultaneous changes can obscure.","correct":false,"id":"E"},{"text":"Expand checks to the full affected population","why":"A local demonstration needs appropriate broader validation.","correct":true,"id":"F"},{"text":"Treat the amount of debugging time as proof the conclusion is correct","why":"Plausibility and effort are not substitutes for relevant evidence.","correct":false,"id":"G"},{"text":"Stop when one total looks plausible","why":"Plausibility and effort are not substitutes for relevant evidence.","correct":false,"id":"H"}],"answer":"Targeting a plausible change point can narrow the investigation efficiently. A controlled example helps identify effects that simultaneous changes can obscure. A local demonstration needs appropriate broader validation. Plausibility and effort are not substitutes for relevant evidence.","source":{"anchor":"ksb-b4","guideSha256":"19544c61d4657ced69a0de9a91c60998a3caac5acfd7f29fa94d863d5f1dfbb2","excerpt":"Show how you independently structured an uncertain problem, formed explanations, chose tests and revised your judgement from evidence."},"id":"T44-E2-Q10"}]},{"id":"T45","title":"B5 · Root Cause Analysis","description":"Distinguishing symptoms, mechanisms and root causes with evidence.","questions":[{"ksb":"B5","objective":"Authorised correction","prompt":"Investigation confirms that a reference upload process accepts conflicting effective dates. Another team owns that process. Which response is appropriate?","options":[{"text":"Re-run and reconcile the affected analysis","why":"Approval and verified execution are different steps.","correct":true,"id":"A"},{"text":"Record the cause, action and responsible roles","why":"A traceable record supports future learning and prevention.","correct":true,"id":"B"},{"text":"Change production rules unilaterally because you found the problem","why":"Finding the cause does not automatically grant authority over the source process.","correct":false,"id":"C"},{"text":"Agree the correction with the responsible owner","why":"Finding the cause does not automatically grant authority over the source process.","correct":true,"id":"D"},{"text":"Delete the investigation record after the chart improves","why":"A traceable record supports future learning and prevention.","correct":false,"id":"E"},{"text":"Correct affected records through the approved route","why":"A correction should reflect a justified authoritative rule.","correct":true,"id":"F"},{"text":"Treat the owner's approval as proof the output has already been repaired","why":"Approval and verified execution are different steps.","correct":false,"id":"G"},{"text":"Select arbitrary dates to make the current totals match","why":"A correction should reflect a justified authoritative rule.","correct":false,"id":"H"}],"answer":"Finding the cause does not automatically grant authority over the source process. A correction should reflect a justified authoritative rule. Approval and verified execution are different steps. A traceable record supports future learning and prevention.","source":{"anchor":"ksb-b5","guideSha256":"dd78340b0eb1bf21bc522276c8df9a6086e26a70149be0507bb287ab4145c106","excerpt":"Separate the visible symptom, the immediate mechanism and the underlying cause."},"id":"T45-E2-Q01"},{"ksb":"B5","objective":"Five Whys use","prompt":"A team uses Five Whys to investigate recurring late extracts. Which application is appropriate?","options":[{"text":"Use the questions to organise an evidence-led investigation","why":"The framework guides inquiry but does not validate an explanation by counting questions.","correct":true,"id":"A"},{"text":"Check proposed causes against schedules, logs and responsibilities","why":"Plausibility needs relevant evidence where the claim can be tested.","correct":true,"id":"B"},{"text":"Distinguish an immediate failure from a recurring process issue","why":"A symptom alone does not explain the mechanism or why it recurs.","correct":true,"id":"C"},{"text":"Record uncertainties and alternative explanations","why":"Real investigations may reveal uncertainty or multiple contributing causes.","correct":true,"id":"D"},{"text":"Label the visible delay as the complete root cause","why":"A symptom alone does not explain the mechanism or why it recurs.","correct":false,"id":"E"},{"text":"Accept each answer solely because it sounds reasonable","why":"Plausibility needs relevant evidence where the claim can be tested.","correct":false,"id":"F"},{"text":"Treat the fifth answer as automatically the true cause","why":"The framework guides inquiry but does not validate an explanation by counting questions.","correct":false,"id":"G"},{"text":"Force every incident into one predetermined cause","why":"Real investigations may reveal uncertainty or multiple contributing causes.","correct":false,"id":"H"}],"answer":"The framework guides inquiry but does not validate an explanation by counting questions. Plausibility needs relevant evidence where the claim can be tested. A symptom alone does not explain the mechanism or why it recurs. Real investigations may reveal uncertainty or multiple contributing causes.","source":{"anchor":"ksb-b5","guideSha256":"dd78340b0eb1bf21bc522276c8df9a6086e26a70149be0507bb287ab4145c106","excerpt":"Separate the visible symptom, the immediate mechanism and the underlying cause."},"id":"T45-E2-Q02"},{"ksb":"B5","objective":"Immediate fix versus prevention","prompt":"You repair a report by re-running a failed load, but the scheduler still lacks an alert for that failure. Which account is accurate?","options":[{"text":"Test the recovery and proposed monitoring behaviour","why":"A proposal must be implemented and checked before being claimed as effective.","correct":true,"id":"A"},{"text":"Claim all future load failures are prevented by successful re-running","why":"A symptom and a recovery action do not establish elimination of every underlying failure mechanism.","correct":false,"id":"B"},{"text":"The re-run addresses the immediate missing output","why":"Recovery of this instance does not necessarily prevent another unnoticed failure.","correct":true,"id":"C"},{"text":"Describe the original absence of data as the entire root cause","why":"A symptom and a recovery action do not establish elimination of every underlying failure mechanism.","correct":false,"id":"D"},{"text":"The re-run alone proves the underlying process risk is removed","why":"Recovery of this instance does not necessarily prevent another unnoticed failure.","correct":false,"id":"E"},{"text":"An appropriate alert and response owner may reduce recurrence impact","why":"Monitoring needs an operational response, not just a notification mechanism.","correct":true,"id":"F"},{"text":"An alert is sufficient without anyone responsible for responding","why":"Monitoring needs an operational response, not just a notification mechanism.","correct":false,"id":"G"},{"text":"Treat writing an alert specification as verified deployment","why":"A proposal must be implemented and checked before being claimed as effective.","correct":false,"id":"H"}],"answer":"Recovery of this instance does not necessarily prevent another unnoticed failure. Monitoring needs an operational response, not just a notification mechanism. A proposal must be implemented and checked before being claimed as effective. A symptom and a recovery action do not establish elimination of every underlying failure mechanism.","source":{"anchor":"ksb-b5","guideSha256":"dd78340b0eb1bf21bc522276c8df9a6086e26a70149be0507bb287ab4145c106","excerpt":"Separate the visible symptom, the immediate mechanism and the underlying cause."},"id":"T45-E2-Q03"},{"ksb":"B5","objective":"Alternative explanations","prompt":"Missing rows could result from an extraction cutoff, an inner join or a dashboard filter. Which investigation is systematic?","options":[{"text":"Accept matching totals as proof the same records remain","why":"Two different populations can have the same count.","correct":false,"id":"A"},{"text":"Use the findings to narrow and revise the explanation","why":"A systematic investigation updates its conclusions as evidence arrives.","correct":true,"id":"B"},{"text":"Keep the first suspected cause regardless of contrary results","why":"A systematic investigation updates its conclusions as evidence arrives.","correct":false,"id":"C"},{"text":"Inspect only the final displayed count","why":"Intermediate checks help locate where the records are lost.","correct":false,"id":"D"},{"text":"Change all filters and joins simultaneously","why":"Controlled checks make it easier to attribute the observed effect to a particular mechanism.","correct":false,"id":"E"},{"text":"Test the specific inclusion rules at the suspected stage","why":"Controlled checks make it easier to attribute the observed effect to a particular mechanism.","correct":true,"id":"F"},{"text":"Compare counts at each stage of the pipeline","why":"Intermediate checks help locate where the records are lost.","correct":true,"id":"G"},{"text":"Reconcile affected record identities, not just totals","why":"Two different populations can have the same count.","correct":true,"id":"H"}],"answer":"Intermediate checks help locate where the records are lost. Controlled checks make it easier to attribute the observed effect to a particular mechanism. Two different populations can have the same count. A systematic investigation updates its conclusions as evidence arrives.","source":{"anchor":"ksb-b5","guideSha256":"dd78340b0eb1bf21bc522276c8df9a6086e26a70149be0507bb287ab4145c106","excerpt":"Separate the visible symptom, the immediate mechanism and the underlying cause."},"id":"T45-E2-Q04"},{"ksb":"B5","objective":"Verification after repair","prompt":"A corrected join returns the expected row count. Which further checks support resolution?","options":[{"text":"Check unaffected groups and edge cases","why":"A correction can have unintended effects beyond the original example.","correct":true,"id":"A"},{"text":"Infer implementation from an email saying the change is planned","why":"A plan is not evidence of completed action.","correct":false,"id":"B"},{"text":"Record residual risks and a suitable review point","why":"Verification supports a bounded conclusion, with ongoing risks stated appropriately.","correct":true,"id":"C"},{"text":"Confirm the agreed source or process correction was applied","why":"A plan is not evidence of completed action.","correct":true,"id":"D"},{"text":"Guarantee permanent correctness from one successful run","why":"Verification supports a bounded conclusion, with ongoing risks stated appropriately.","correct":false,"id":"E"},{"text":"Stop because one count matches the expected number","why":"A matching count can still hide wrong matches or values.","correct":false,"id":"F"},{"text":"Reconcile relevant identities and important totals","why":"A matching count can still hide wrong matches or values.","correct":true,"id":"G"},{"text":"Validate only the single example used in the investigation","why":"A correction can have unintended effects beyond the original example.","correct":false,"id":"H"}],"answer":"A matching count can still hide wrong matches or values. A correction can have unintended effects beyond the original example. A plan is not evidence of completed action. Verification supports a bounded conclusion, with ongoing risks stated appropriately.","source":{"anchor":"ksb-b5","guideSha256":"dd78340b0eb1bf21bc522276c8df9a6086e26a70149be0507bb287ab4145c106","excerpt":"Separate the visible symptom, the immediate mechanism and the underlying cause."},"id":"T45-E2-Q05"},{"ksb":"B5","objective":"Preventing recurrence","prompt":"An upstream form allows blank service codes, causing repeated manual mapping work. Which solution addresses recurrence?","options":[{"text":"Assign ownership for the preventive control","why":"Sustained prevention needs an explicit responsible owner.","correct":true,"id":"A"},{"text":"Assume the reporting analyst will monitor it forever without agreement","why":"Sustained prevention needs an explicit responsible owner.","correct":false,"id":"B"},{"text":"Rename the missing-code category to make the issue less visible","why":"Exclusion or relabelling can hide the symptom without resolving its origin.","correct":false,"id":"C"},{"text":"Declare the problem impossible after one clean batch","why":"Follow-up evidence is needed to assess whether the control is effective over time.","correct":false,"id":"D"},{"text":"Consider appropriate entry validation or a justified exception process","why":"Addressing the source mechanism can reduce recurrence rather than only repair each output.","correct":true,"id":"E"},{"text":"Monitor later batches for the same failure","why":"Follow-up evidence is needed to assess whether the control is effective over time.","correct":true,"id":"F"},{"text":"Repeat the same undocumented manual fix indefinitely","why":"Addressing the source mechanism can reduce recurrence rather than only repair each output.","correct":false,"id":"G"},{"text":"Remove the affected service from all reporting","why":"Exclusion or relabelling can hide the symptom without resolving its origin.","correct":false,"id":"H"}],"answer":"Addressing the source mechanism can reduce recurrence rather than only repair each output. Sustained prevention needs an explicit responsible owner. Follow-up evidence is needed to assess whether the control is effective over time. Exclusion or relabelling can hide the symptom without resolving its origin.","source":{"anchor":"ksb-b5","guideSha256":"dd78340b0eb1bf21bc522276c8df9a6086e26a70149be0507bb287ab4145c106","excerpt":"Separate the visible symptom, the immediate mechanism and the underlying cause."},"id":"T45-E2-Q06"},{"ksb":"B5","objective":"Learning across projects","prompt":"A duplicate-key incident is resolved in one pipeline. Which broader action is justified?","options":[{"text":"Count distribution of a lessons document as proof of prevention","why":"Communication is useful but does not demonstrate that controls were applied or effective.","correct":false,"id":"A"},{"text":"Retain responsibility and monitoring for the corrected process","why":"Ownership should follow the agreed operational roles rather than mere discovery of the issue.","correct":true,"id":"B"},{"text":"Assume every other report has the identical defect","why":"A lesson can motivate checks without establishing unobserved failures.","correct":false,"id":"C"},{"text":"Evaluate whether preventive checks actually reduce recurrence","why":"Communication is useful but does not demonstrate that controls were applied or effective.","correct":true,"id":"D"},{"text":"Transfer all future accountability to the person who first noticed the error","why":"Ownership should follow the agreed operational roles rather than mere discovery of the issue.","correct":false,"id":"E"},{"text":"Assess whether similar controls are relevant in related pipelines","why":"A lesson can motivate checks without establishing unobserved failures.","correct":true,"id":"F"},{"text":"Circulate restricted source records broadly to illustrate the story","why":"Learning can be shared through suitable explanations without unnecessary disclosure.","correct":false,"id":"G"},{"text":"Share the verified mechanism and prevention approach with relevant colleagues","why":"Learning can be shared through suitable explanations without unnecessary disclosure.","correct":true,"id":"H"}],"answer":"A lesson can motivate checks without establishing unobserved failures. Learning can be shared through suitable explanations without unnecessary disclosure. Communication is useful but does not demonstrate that controls were applied or effective. Ownership should follow the agreed operational roles rather than mere discovery of the issue.","source":{"anchor":"ksb-b5","guideSha256":"dd78340b0eb1bf21bc522276c8df9a6086e26a70149be0507bb287ab4145c106","excerpt":"Separate the visible symptom, the immediate mechanism and the underlying cause."},"id":"T45-E2-Q07"},{"ksb":"B5","objective":"Root-cause evidence","prompt":"You suspect a missing validation rule permits duplicate service keys. Which evidence would strengthen that explanation?","options":[{"text":"Check whether other plausible causes explain the discrepancy","why":"Testing alternatives helps distinguish a supported cause from confirmation bias.","correct":true,"id":"A"},{"text":"Treat one colleague's guess as equivalent to a reproduced mechanism","why":"Root-cause conclusions should be bounded by the actual evidence and context.","correct":false,"id":"B"},{"text":"Conclude every duplicate in every system has the same cause","why":"Root-cause conclusions should be bounded by the actual evidence and context.","correct":false,"id":"C"},{"text":"Infer multiplication solely from the final dashboard's colour","why":"The relevant evidence concerns record relationships and output counts.","correct":false,"id":"D"},{"text":"Search only for examples supporting the preferred explanation","why":"Testing alternatives helps distinguish a supported cause from confirmation bias.","correct":false,"id":"E"},{"text":"Demonstrate the resulting row multiplication in a controlled join","why":"The relevant evidence concerns record relationships and output counts.","correct":true,"id":"F"},{"text":"Rely only on a general statement that validation is weak","why":"A reproducible mechanism gives more specific support than a broad criticism.","correct":false,"id":"G"},{"text":"Show how the duplicate input passes the current rule","why":"A reproducible mechanism gives more specific support than a broad criticism.","correct":true,"id":"H"}],"answer":"A reproducible mechanism gives more specific support than a broad criticism. The relevant evidence concerns record relationships and output counts. Testing alternatives helps distinguish a supported cause from confirmation bias. Root-cause conclusions should be bounded by the actual evidence and context.","source":{"anchor":"ksb-b5","guideSha256":"dd78340b0eb1bf21bc522276c8df9a6086e26a70149be0507bb287ab4145c106","excerpt":"Separate the visible symptom, the immediate mechanism and the underlying cause."},"id":"T45-E2-Q08"},{"ksb":"B5","objective":"Honest investigation outcome","prompt":"Several checks narrow an issue to an upstream process, but the exact mechanism remains unconfirmed. Which report is appropriate?","options":[{"text":"Present containment as proof that the mechanism is fully understood","why":"Managing the immediate risk and establishing the cause are different achievements.","correct":false,"id":"A"},{"text":"Separate verified findings from the remaining hypothesis","why":"The conclusion should reflect the actual strength of evidence.","correct":true,"id":"B"},{"text":"Close the issue solely because a temporary workaround exists","why":"A workaround may leave a cause unresolved, while partial findings can still narrow the investigation usefully.","correct":false,"id":"C"},{"text":"Fill the gap with a plausible invented technical detail","why":"An unknown should remain explicit rather than be replaced by fabrication.","correct":false,"id":"D"},{"text":"Claim that uncertainty means none of the completed checks had value","why":"A workaround may leave a cause unresolved, while partial findings can still narrow the investigation usefully.","correct":false,"id":"E"},{"text":"Explain the next check or responsible investigation route","why":"An unknown should remain explicit rather than be replaced by fabrication.","correct":true,"id":"F"},{"text":"Describe the preferred hypothesis as the proven root cause","why":"The conclusion should reflect the actual strength of evidence.","correct":false,"id":"G"},{"text":"Apply justified containment while the cause is investigated","why":"Managing the immediate risk and establishing the cause are different achievements.","correct":true,"id":"H"}],"answer":"The conclusion should reflect the actual strength of evidence. An unknown should remain explicit rather than be replaced by fabrication. Managing the immediate risk and establishing the cause are different achievements. A workaround may leave a cause unresolved, while partial findings can still narrow the investigation usefully.","source":{"anchor":"ksb-b5","guideSha256":"dd78340b0eb1bf21bc522276c8df9a6086e26a70149be0507bb287ab4145c106","excerpt":"Separate the visible symptom, the immediate mechanism and the underlying cause."},"id":"T45-E2-Q09"},{"ksb":"B5","objective":"Symptom and cause","prompt":"A weekly report suddenly doubles some totals after a reference-file update. Which investigation addresses the unknown cause?","options":[{"text":"Attribute the error to the chart because that is where it appears","why":"A visible output can display a problem created upstream.","correct":false,"id":"A"},{"text":"Test whether the changed reference rows explain the multiplication","why":"The suspected cause needs a check showing how it produces the observed effect.","correct":true,"id":"B"},{"text":"Investigate why conflicting reference keys entered the workflow","why":"Prevention requires attention to the underlying process that allowed the conflicting input.","correct":true,"id":"C"},{"text":"Compare keys and join cardinality before and after the update","why":"A visible output can display a problem created upstream.","correct":true,"id":"D"},{"text":"Start correcting chart values manually","why":"Reproduction helps locate the mechanism rather than only hide its visible symptom.","correct":false,"id":"E"},{"text":"Reproduce the discrepancy using the affected inputs","why":"Reproduction helps locate the mechanism rather than only hide its visible symptom.","correct":true,"id":"F"},{"text":"Stop after deleting one duplicate output row","why":"Prevention requires attention to the underlying process that allowed the conflicting input.","correct":false,"id":"G"},{"text":"Accept the timing coincidence as sufficient proof","why":"The suspected cause needs a check showing how it produces the observed effect.","correct":false,"id":"H"}],"answer":"Reproduction helps locate the mechanism rather than only hide its visible symptom. A visible output can display a problem created upstream. The suspected cause needs a check showing how it produces the observed effect. Prevention requires attention to the underlying process that allowed the conflicting input.","source":{"anchor":"ksb-b5","guideSha256":"dd78340b0eb1bf21bc522276c8df9a6086e26a70149be0507bb287ab4145c106","excerpt":"Separate the visible symptom, the immediate mechanism and the underlying cause."},"id":"T45-E2-Q10"}]},{"id":"T46","title":"B6 · Resilience & Lessons Learned","description":"Constructive responses, support, honest outcomes and transferable learning.","questions":[{"ksb":"B6","objective":"Unsuccessful model","prompt":"Your predictive model fails to beat a simple baseline after careful validation. Which response demonstrates resilience and learning?","options":[{"text":"Report the result honestly and assess what it means for use","why":"Resilience does not require misrepresenting an unfavourable finding.","correct":true,"id":"A"},{"text":"Record the lesson for later model selection","why":"A useful reflection explains what changed in understanding or future practice.","correct":true,"id":"B"},{"text":"Repeat the same tuning indefinitely without reassessing the approach","why":"Constructive persistence includes reconsidering the method when evidence warrants it.","correct":false,"id":"C"},{"text":"State only that the project was challenging","why":"A useful reflection explains what changed in understanding or future practice.","correct":false,"id":"D"},{"text":"Deploy the complex model solely because much effort was invested","why":"Prior effort does not establish future usefulness.","correct":false,"id":"E"},{"text":"Investigate specific limitations in features, data or design","why":"Constructive persistence includes reconsidering the method when evidence warrants it.","correct":true,"id":"F"},{"text":"Identify a concrete next step or justified simpler solution","why":"Prior effort does not establish future usefulness.","correct":true,"id":"G"},{"text":"Hide the baseline to present the model as successful","why":"Resilience does not require misrepresenting an unfavourable finding.","correct":false,"id":"H"}],"answer":"Resilience does not require misrepresenting an unfavourable finding. Constructive persistence includes reconsidering the method when evidence warrants it. Prior effort does not establish future usefulness. A useful reflection explains what changed in understanding or future practice.","source":{"anchor":"ksb-b6","guideSha256":"a26a2f78cc1df19af5ec0ad9d32ce26fa6440cfc9aedf519f4e1bf1b739babb3","excerpt":"Give a specific challenge and explain a constructive response: reassess, seek appropriate support, break work into manageable steps, use feedback and maintain quality."},"id":"T46-E2-Q01"},{"ksb":"B6","objective":"Difficult debugging","prompt":"A recurring error persists after your first fix. Which behaviour is constructive?","options":[{"text":"Reassess the evidence and break the investigation into smaller checks","why":"A failed attempt can indicate that the working explanation needs revision.","correct":true,"id":"A"},{"text":"Avoid all help to prove resilience","why":"Relevant support can help resolve a difficult problem without removing personal responsibility.","correct":false,"id":"B"},{"text":"Describe the repeated failure as proof no learning is possible","why":"Arbitrary removal and absolute defeat do not follow from an unsuccessful first attempt.","correct":false,"id":"C"},{"text":"Delete difficult records without an analytical reason","why":"Arbitrary removal and absolute defeat do not follow from an unsuccessful first attempt.","correct":false,"id":"D"},{"text":"Claim the issue is solved to avoid disappointing stakeholders","why":"Accurate status supports a professional response to the remaining challenge.","correct":false,"id":"E"},{"text":"Keep applying the same fix without testing its assumptions","why":"A failed attempt can indicate that the working explanation needs revision.","correct":false,"id":"F"},{"text":"Preserve quality and communicate realistic progress","why":"Accurate status supports a professional response to the remaining challenge.","correct":true,"id":"G"},{"text":"Seek appropriate support with a clear account of what you tried","why":"Relevant support can help resolve a difficult problem without removing personal responsibility.","correct":true,"id":"H"}],"answer":"A failed attempt can indicate that the working explanation needs revision. Relevant support can help resolve a difficult problem without removing personal responsibility. Accurate status supports a professional response to the remaining challenge. Arbitrary removal and absolute defeat do not follow from an unsuccessful first attempt.","source":{"anchor":"ksb-b6","guideSha256":"a26a2f78cc1df19af5ec0ad9d32ce26fa6440cfc9aedf519f4e1bf1b739babb3","excerpt":"Give a specific challenge and explain a constructive response: reassess, seek appropriate support, break work into manageable steps, use feedback and maintain quality."},"id":"T46-E2-Q02"},{"ksb":"B6","objective":"Recovering after review","prompt":"A reviewer identifies an important calculation error before release. Which response demonstrates resilience?","options":[{"text":"Defend the formula solely because you wrote it","why":"Constructive response focuses on the evidence and correction rather than ownership.","correct":false,"id":"A"},{"text":"Claim the reviewer performed no useful role","why":"Accurate attribution and reporting are part of a professional learning response.","correct":false,"id":"B"},{"text":"Acknowledge and investigate the error","why":"Constructive response focuses on the evidence and correction rather than ownership.","correct":true,"id":"C"},{"text":"Describe the original output as correct after privately changing it","why":"Accurate attribution and reporting are part of a professional learning response.","correct":false,"id":"D"},{"text":"Correct and revalidate affected outputs","why":"Dependent calculations may also require repair and checking.","correct":true,"id":"E"},{"text":"Explain the impact and record a preventive lesson","why":"Transparent correction can support trust and future quality.","correct":true,"id":"F"},{"text":"Hide the correction history to preserve confidence","why":"Transparent correction can support trust and future quality.","correct":false,"id":"G"},{"text":"Change only the visible headline number","why":"Dependent calculations may also require repair and checking.","correct":false,"id":"H"}],"answer":"Constructive response focuses on the evidence and correction rather than ownership. Dependent calculations may also require repair and checking. Transparent correction can support trust and future quality. Accurate attribution and reporting are part of a professional learning response.","source":{"anchor":"ksb-b6","guideSha256":"a26a2f78cc1df19af5ec0ad9d32ce26fa6440cfc9aedf519f4e1bf1b739babb3","excerpt":"Give a specific challenge and explain a constructive response: reassess, seek appropriate support, break work into manageable steps, use feedback and maintain quality."},"id":"T46-E2-Q03"},{"ksb":"B6","objective":"Sustainable response","prompt":"A difficult task is taking longer than expected and you are making repeated mistakes through fatigue. Which professional response is appropriate?","options":[{"text":"Claim that effort alone guarantees a correct result","why":"Effort needs to be connected to effective methods, checks and realistic planning.","correct":false,"id":"A"},{"text":"Hide the mistakes to maintain an image of productivity","why":"Accurate communication helps protect the quality of the work.","correct":false,"id":"B"},{"text":"Continue indefinitely without reviewing quality or workload","why":"Constructive resilience includes maintaining effective, sustainable working practices.","correct":false,"id":"C"},{"text":"Treat all assistance as evidence of incompetence","why":"Support can improve both the outcome and the learning from the challenge.","correct":false,"id":"D"},{"text":"Identify how future estimates or checkpoints could improve","why":"Effort needs to be connected to effective methods, checks and realistic planning.","correct":true,"id":"E"},{"text":"Use appropriate support and checking arrangements","why":"Support can improve both the outcome and the learning from the challenge.","correct":true,"id":"F"},{"text":"Reassess priorities and seek a realistic plan with the relevant people","why":"Constructive resilience includes maintaining effective, sustainable working practices.","correct":true,"id":"G"},{"text":"Communicate the risk to accuracy and delivery","why":"Accurate communication helps protect the quality of the work.","correct":true,"id":"H"}],"answer":"Constructive resilience includes maintaining effective, sustainable working practices. Support can improve both the outcome and the learning from the challenge. Accurate communication helps protect the quality of the work. Effort needs to be connected to effective methods, checks and realistic planning.","source":{"anchor":"ksb-b6","guideSha256":"a26a2f78cc1df19af5ec0ad9d32ce26fa6440cfc9aedf519f4e1bf1b739babb3","excerpt":"Give a specific challenge and explain a constructive response: reassess, seek appropriate support, break work into manageable steps, use feedback and maintain quality."},"id":"T46-E2-Q04"},{"ksb":"B6","objective":"Critical feedback","prompt":"A stakeholder says your explanation is too technical to support their decision. Which response demonstrates learning?","options":[{"text":"Remove all caveats to make the message shorter","why":"Adaptation should retain material limits needed for interpretation.","correct":false,"id":"A"},{"text":"Clarify which parts were difficult and what decision they need","why":"Correct analysis can still require a clearer explanation for its audience.","correct":true,"id":"B"},{"text":"Claim positive feedback that was not actually received","why":"Reflection should be grounded in genuine observations.","correct":false,"id":"C"},{"text":"Check whether the revised explanation works better","why":"Feedback on the revised communication provides evidence of improvement.","correct":true,"id":"D"},{"text":"Dismiss the feedback because the calculations were correct","why":"Correct analysis can still require a clearer explanation for its audience.","correct":false,"id":"E"},{"text":"Revise the language and level of detail while preserving meaning","why":"Adaptation should retain material limits needed for interpretation.","correct":true,"id":"F"},{"text":"Assume rewriting automatically resolves the misunderstanding","why":"Feedback on the revised communication provides evidence of improvement.","correct":false,"id":"G"},{"text":"Record a specific communication lesson for later briefings","why":"Reflection should be grounded in genuine observations.","correct":true,"id":"H"}],"answer":"Correct analysis can still require a clearer explanation for its audience. Adaptation should retain material limits needed for interpretation. Feedback on the revised communication provides evidence of improvement. Reflection should be grounded in genuine observations.","source":{"anchor":"ksb-b6","guideSha256":"a26a2f78cc1df19af5ec0ad9d32ce26fa6440cfc9aedf519f4e1bf1b739babb3","excerpt":"Give a specific challenge and explain a constructive response: reassess, seek appropriate support, break work into manageable steps, use feedback and maintain quality."},"id":"T46-E2-Q05"},{"ksb":"B6","objective":"Lost preparation time","prompt":"An access delay reduces the time available before delivery. Which response preserves resilience and standards?","options":[{"text":"Retain essential validation and appropriate handling","why":"Resilience involves a realistic response to the delay; undisclosed reductions in assurance can undermine the quality and credibility of delivery.","correct":true,"id":"A"},{"text":"Keep the original delivery promise by reducing validation without discussing the resulting risk","why":"Resilience involves a realistic response to the delay; undisclosed reductions in assurance can undermine the quality and credibility of delivery.","correct":false,"id":"B"},{"text":"Promise unchanged scope without assessing the remaining work","why":"A constructive response considers feasibility rather than unsupported reassurance.","correct":false,"id":"C"},{"text":"Conceal the delay until the deadline passes","why":"Clear communication enables realistic adjustment of expectations.","correct":false,"id":"D"},{"text":"Treat any deadline adjustment as proof the project has no value","why":"Honest adaptation can preserve a useful outcome without fabricating completion.","correct":false,"id":"E"},{"text":"Agree a reduced scope or revised timing where needed","why":"A constructive response considers feasibility rather than unsupported reassurance.","correct":true,"id":"F"},{"text":"Invent missing results to fill the gap","why":"Honest adaptation can preserve a useful outcome without fabricating completion.","correct":false,"id":"G"},{"text":"Reprioritise feasible work and explain the constraint","why":"Clear communication enables realistic adjustment of expectations.","correct":true,"id":"H"}],"answer":"Clear communication enables realistic adjustment of expectations. A constructive response considers feasibility rather than unsupported reassurance. Resilience involves a realistic response to the delay; undisclosed reductions in assurance can undermine the quality and credibility of delivery. Honest adaptation can preserve a useful outcome without fabricating completion.","source":{"anchor":"ksb-b6","guideSha256":"a26a2f78cc1df19af5ec0ad9d32ce26fa6440cfc9aedf519f4e1bf1b739babb3","excerpt":"Give a specific challenge and explain a constructive response: reassess, seek appropriate support, break work into manageable steps, use feedback and maintain quality."},"id":"T46-E2-Q06"},{"ksb":"B6","objective":"Revising a belief","prompt":"You expected one service to perform better, but checked analysis contradicts that expectation. Which response is constructive?","options":[{"text":"Carry the lesson into future planning or interpretation","why":"The lesson should remain bounded by the evidence and circumstances.","correct":true,"id":"A"},{"text":"Infer the new ranking must hold permanently in every context","why":"The lesson should remain bounded by the evidence and circumstances.","correct":false,"id":"B"},{"text":"Explain how the evidence changed your understanding","why":"Reflection is stronger when it truthfully shows the change in judgement.","correct":true,"id":"C"},{"text":"Accept a supported conclusion within its limits","why":"A desired result is not a justification for selective analysis.","correct":true,"id":"D"},{"text":"Present the initial belief as though it had always matched the finding","why":"Reflection is stronger when it truthfully shows the change in judgement.","correct":false,"id":"E"},{"text":"Search only for reasons to discard the unfavourable result","why":"Learning requires openness to evidence that challenges an expectation.","correct":false,"id":"F"},{"text":"Examine the result and assumptions fairly","why":"Learning requires openness to evidence that challenges an expectation.","correct":true,"id":"G"},{"text":"Change the method until the expected ranking appears","why":"A desired result is not a justification for selective analysis.","correct":false,"id":"H"}],"answer":"Learning requires openness to evidence that challenges an expectation. A desired result is not a justification for selective analysis. Reflection is stronger when it truthfully shows the change in judgement. The lesson should remain bounded by the evidence and circumstances.","source":{"anchor":"ksb-b6","guideSha256":"a26a2f78cc1df19af5ec0ad9d32ce26fa6440cfc9aedf519f4e1bf1b739babb3","excerpt":"Give a specific challenge and explain a constructive response: reassess, seek appropriate support, break work into manageable steps, use feedback and maintain quality."},"id":"T46-E2-Q07"},{"ksb":"B6","objective":"Learning specificity","prompt":"You write 'I learned a lot' after an analytical setback. Which additions make the reflection useful?","options":[{"text":"Explain what evidence changed your understanding","why":"The learning account should show how the experience affected judgement.","correct":true,"id":"A"},{"text":"State a concrete change to future work","why":"An actionable improvement is more credible than a universal guarantee.","correct":true,"id":"B"},{"text":"Describe a relevant opportunity to check the improvement","why":"Application or later review can show whether the lesson affected behaviour.","correct":true,"id":"C"},{"text":"Describe only the eventual positive outcome","why":"The learning account should show how the experience affected judgement.","correct":false,"id":"D"},{"text":"Promise that no future problem will occur","why":"An actionable improvement is more credible than a universal guarantee.","correct":false,"id":"E"},{"text":"Replace the phrase with another general statement about hard work","why":"A specific lesson is more actionable than a broad self-description.","correct":false,"id":"F"},{"text":"Treat writing the reflection as proof future practice changed","why":"Application or later review can show whether the lesson affected behaviour.","correct":false,"id":"G"},{"text":"Identify the particular assumption or practice that failed","why":"A specific lesson is more actionable than a broad self-description.","correct":true,"id":"H"}],"answer":"A specific lesson is more actionable than a broad self-description. The learning account should show how the experience affected judgement. An actionable improvement is more credible than a universal guarantee. Application or later review can show whether the lesson affected behaviour.","source":{"anchor":"ksb-b6","guideSha256":"a26a2f78cc1df19af5ec0ad9d32ce26fa6440cfc9aedf519f4e1bf1b739babb3","excerpt":"Give a specific challenge and explain a constructive response: reassess, seek appropriate support, break work into manageable steps, use feedback and maintain quality."},"id":"T46-E2-Q08"},{"ksb":"B6","objective":"Imperfect outcome","prompt":"A project delivers a useful core report but an optional feature cannot be completed. Which account is resilient and honest?","options":[{"text":"Report the core release as meeting the original full scope because its main feature works","why":"A useful partial delivery should distinguish completed value from unmet scope; evidence should accurately state limitations and agreed follow-up.","correct":false,"id":"A"},{"text":"Treat any incomplete feature as proof the whole project failed","why":"A bounded outcome can still be useful and provide learning.","correct":false,"id":"B"},{"text":"Describe the decisions made to preserve the essential requirement","why":"A bounded outcome can still be useful and provide learning.","correct":true,"id":"C"},{"text":"Explain what would improve planning or execution next time","why":"Reflection should consider your own decisions and lessons as well as external constraints.","correct":true,"id":"D"},{"text":"Explain the achieved outcome and the remaining limitation","why":"A truthful account distinguishes what succeeded from what remains incomplete.","correct":true,"id":"E"},{"text":"Attribute every difficulty to others without examining your choices","why":"Reflection should consider your own decisions and lessons as well as external constraints.","correct":false,"id":"F"},{"text":"Remove the original scope record to conceal the omission","why":"A useful partial delivery should distinguish completed value from unmet scope; evidence should accurately state limitations and agreed follow-up.","correct":false,"id":"G"},{"text":"Present every planned feature as delivered","why":"A truthful account distinguishes what succeeded from what remains incomplete.","correct":false,"id":"H"}],"answer":"A truthful account distinguishes what succeeded from what remains incomplete. A bounded outcome can still be useful and provide learning. Reflection should consider your own decisions and lessons as well as external constraints. A useful partial delivery should distinguish completed value from unmet scope; evidence should accurately state limitations and agreed follow-up.","source":{"anchor":"ksb-b6","guideSha256":"a26a2f78cc1df19af5ec0ad9d32ce26fa6440cfc9aedf519f4e1bf1b739babb3","excerpt":"Give a specific challenge and explain a constructive response: reassess, seek appropriate support, break work into manageable steps, use feedback and maintain quality."},"id":"T46-E2-Q09"},{"ksb":"B6","objective":"Repeated lesson","prompt":"A second project encounters the same join issue as the first. Which response demonstrates learning from experience?","options":[{"text":"Repeat the old workaround without reviewing its limits","why":"A recurrence should prompt assessment of whether the approach addresses the cause.","correct":false,"id":"A"},{"text":"State only that you were more resilient","why":"Specific changes show how the experience influenced behaviour.","correct":false,"id":"B"},{"text":"Claim the first lesson eliminated every future risk","why":"An honest account can acknowledge incomplete prevention and identify further improvement.","correct":false,"id":"C"},{"text":"Assume the existence of a lessons document means the issue was prevented","why":"A written lesson is different from an implemented control.","correct":false,"id":"D"},{"text":"Check whether the earlier prevention was actually adopted","why":"A written lesson is different from an implemented control.","correct":true,"id":"E"},{"text":"Apply and validate a relevant improved check","why":"A recurrence should prompt assessment of whether the approach addresses the cause.","correct":true,"id":"F"},{"text":"Omit the recurrence from reflection because it is uncomfortable","why":"An honest account can acknowledge incomplete prevention and identify further improvement.","correct":false,"id":"G"},{"text":"Explain what changed in your process this time","why":"Specific changes show how the experience influenced behaviour.","correct":true,"id":"H"}],"answer":"A written lesson is different from an implemented control. A recurrence should prompt assessment of whether the approach addresses the cause. Specific changes show how the experience influenced behaviour. An honest account can acknowledge incomplete prevention and identify further improvement.","source":{"anchor":"ksb-b6","guideSha256":"a26a2f78cc1df19af5ec0ad9d32ce26fa6440cfc9aedf519f4e1bf1b739babb3","excerpt":"Give a specific challenge and explain a constructive response: reassess, seek appropriate support, break work into manageable steps, use feedback and maintain quality."},"id":"T46-E2-Q10"}]},{"id":"T47","title":"B7 · Flexibility in Contextual Shifts","description":"Adapting to changes in scope, priorities or responsibilities.","questions":[{"ksb":"B7","objective":"Audience shift","prompt":"A technical investigation is redirected into a public-facing service briefing. Which changes should be considered?","options":[{"text":"Agree the revised purpose and review process","why":"A public-facing use can change governance, interpretation and stakeholder needs.","correct":true,"id":"A"},{"text":"Review permissions and disclosure risks for wider sharing","why":"Wider distribution can change the relevant handling and release requirements.","correct":true,"id":"B"},{"text":"Remove uncertainty to make the public message simpler","why":"Audience adaptation should not misrepresent the strength of the evidence.","correct":false,"id":"C"},{"text":"Reuse the raw technical notebook without checking its suitability","why":"A different audience can require a different presentation and level of explanation.","correct":false,"id":"D"},{"text":"Preserve material limitations in accessible wording","why":"Audience adaptation should not misrepresent the strength of the evidence.","correct":true,"id":"E"},{"text":"Reassess language, detail and explanation for the new audience","why":"A different audience can require a different presentation and level of explanation.","correct":true,"id":"F"},{"text":"Treat publication as a purely cosmetic output change","why":"A public-facing use can change governance, interpretation and stakeholder needs.","correct":false,"id":"G"},{"text":"Assume internal access decisions automatically permit public release","why":"Wider distribution can change the relevant handling and release requirements.","correct":false,"id":"H"}],"answer":"A different audience can require a different presentation and level of explanation. Wider distribution can change the relevant handling and release requirements. Audience adaptation should not misrepresent the strength of the evidence. A public-facing use can change governance, interpretation and stakeholder needs.","source":{"anchor":"ksb-b7","guideSha256":"d5e4802223d7b6d3188731e9612e51c8f64a5b2d86c85188adaff8506b58ab9d","excerpt":"Describe a change in project scope, organisational direction or responsibilities and how you adapted the plan."},"id":"T47-E2-Q01"},{"ksb":"B7","objective":"New responsibilities","prompt":"You take over maintenance of a recurring report while continuing part of your original analytical work. Which response demonstrates flexibility?","options":[{"text":"Assume every previous deadline remains feasible without discussion","why":"Changed workload requires a realistic review of commitments.","correct":false,"id":"A"},{"text":"Hide uncertainty about critical processes","why":"Appropriate support helps maintain reliable delivery during the transition.","correct":false,"id":"B"},{"text":"Treat ownership transfer as proof you already know the workflow","why":"New responsibility may require learning and coordination.","correct":false,"id":"C"},{"text":"Clarify the new responsibilities and priorities","why":"Changed workload requires a realistic review of commitments.","correct":true,"id":"D"},{"text":"Identify handover needs, dependencies and skill gaps","why":"New responsibility may require learning and coordination.","correct":true,"id":"E"},{"text":"Treat the change as merely a missing-file incident","why":"The account should reflect the actual responsibility shift and truthful attribution.","correct":false,"id":"F"},{"text":"Claim responsibility for past work completed before your involvement","why":"The account should reflect the actual responsibility shift and truthful attribution.","correct":false,"id":"G"},{"text":"Agree support and a workable transition","why":"Appropriate support helps maintain reliable delivery during the transition.","correct":true,"id":"H"}],"answer":"Changed workload requires a realistic review of commitments. New responsibility may require learning and coordination. Appropriate support helps maintain reliable delivery during the transition. The account should reflect the actual responsibility shift and truthful attribution.","source":{"anchor":"ksb-b7","guideSha256":"d5e4802223d7b6d3188731e9612e51c8f64a5b2d86c85188adaff8506b58ab9d","excerpt":"Describe a change in project scope, organisational direction or responsibilities and how you adapted the plan."},"id":"T47-E2-Q02"},{"ksb":"B7","objective":"Strategic change","prompt":"A project shifts from an annual performance review to an urgent operational capacity briefing. Which adaptation addresses the changed context?","options":[{"text":"Reconfirm the decision, audience and time horizon","why":"A new purpose can require different information and analytical scope.","correct":true,"id":"A"},{"text":"Promise both complete scopes within the original effort without assessment","why":"The change needs a realistic trade-off in work and delivery.","correct":false,"id":"B"},{"text":"Treat the pivot as a title-only edit","why":"A changed decision context can affect inputs and analysis as well as presentation.","correct":false,"id":"C"},{"text":"Explain exclusions and manage stakeholder feedback","why":"The outcome should reflect the agreed revised scope truthfully.","correct":true,"id":"D"},{"text":"Claim both briefs were fully delivered regardless of omitted work","why":"The outcome should reflect the agreed revised scope truthfully.","correct":false,"id":"E"},{"text":"Keep the annual-review questions unchanged because work has started","why":"A new purpose can require different information and analytical scope.","correct":false,"id":"F"},{"text":"Agree a feasible revised output and priorities","why":"The change needs a realistic trade-off in work and delivery.","correct":true,"id":"G"},{"text":"Revisit data, methods and relevant risks","why":"A changed decision context can affect inputs and analysis as well as presentation.","correct":true,"id":"H"}],"answer":"A new purpose can require different information and analytical scope. The change needs a realistic trade-off in work and delivery. A changed decision context can affect inputs and analysis as well as presentation. The outcome should reflect the agreed revised scope truthfully.","source":{"anchor":"ksb-b7","guideSha256":"d5e4802223d7b6d3188731e9612e51c8f64a5b2d86c85188adaff8506b58ab9d","excerpt":"Describe a change in project scope, organisational direction or responsibilities and how you adapted the plan."},"id":"T47-E2-Q03"},{"ksb":"B7","objective":"Objective reprioritisation","prompt":"A sponsor changes the objective from reducing average duration to protecting vulnerable users from extreme delays. Which analytical response is appropriate?","options":[{"text":"Assume the new objective permits unrestricted sensitive information use","why":"A worthwhile goal does not remove appropriate handling and ethical assessment.","correct":false,"id":"A"},{"text":"Rename the existing mean as an extreme-delay measure","why":"A changed label does not implement the new analytical meaning.","correct":false,"id":"B"},{"text":"Assess ethical, data and access implications","why":"A worthwhile goal does not remove appropriate handling and ethical assessment.","correct":true,"id":"C"},{"text":"Evaluate suitable measures and methods for the new aim","why":"A changed label does not implement the new analytical meaning.","correct":true,"id":"D"},{"text":"Reconfirm the target population and decision criteria","why":"The revised objective may need attention to tails, subgroups and different consequences.","correct":true,"id":"E"},{"text":"Keep optimising only the overall mean without discussion","why":"The revised objective may need attention to tails, subgroups and different consequences.","correct":false,"id":"F"},{"text":"Promise the revised outcome before checking data availability","why":"Shared subject matter does not establish equivalent requirements or feasibility.","correct":false,"id":"G"},{"text":"Claim the old and new objectives are identical because both involve delays","why":"Shared subject matter does not establish equivalent requirements or feasibility.","correct":false,"id":"H"}],"answer":"The revised objective may need attention to tails, subgroups and different consequences. A changed label does not implement the new analytical meaning. A worthwhile goal does not remove appropriate handling and ethical assessment. Shared subject matter does not establish equivalent requirements or feasibility.","source":{"anchor":"ksb-b7","guideSha256":"d5e4802223d7b6d3188731e9612e51c8f64a5b2d86c85188adaff8506b58ab9d","excerpt":"Describe a change in project scope, organisational direction or responsibilities and how you adapted the plan."},"id":"T47-E2-Q04"},{"ksb":"B7","objective":"Reduced resources","prompt":"The project loses a team member and must deliver a smaller approved scope. Which behaviour demonstrates flexibility?","options":[{"text":"Coordinate stakeholder expectations and feedback","why":"Clear communication supports realistic decisions about the revised plan.","correct":true,"id":"A"},{"text":"Keep the original milestone plan unchanged after agreeing the smaller scope","why":"The revised scope and available people need to be reflected in the work plan; a truthful account explains the constraint and resulting decisions.","correct":false,"id":"B"},{"text":"Continue promising every original feature without reassessment","why":"Changed resources affect what can be delivered reliably.","correct":false,"id":"C"},{"text":"Agree priorities and responsibilities under the new capacity","why":"Changed resources affect what can be delivered reliably.","correct":true,"id":"D"},{"text":"Hide the resource change until the final handover","why":"Clear communication supports realistic decisions about the revised plan.","correct":false,"id":"E"},{"text":"Explain the actual delivered outcome and remaining work","why":"The revised scope and available people need to be reflected in the work plan; a truthful account explains the constraint and resulting decisions.","correct":true,"id":"F"},{"text":"Remove validation first because users cannot see it","why":"Reducing scope should not silently undermine essential correctness.","correct":false,"id":"G"},{"text":"Identify essential quality checks and feasible exclusions","why":"Reducing scope should not silently undermine essential correctness.","correct":true,"id":"H"}],"answer":"Changed resources affect what can be delivered reliably. Reducing scope should not silently undermine essential correctness. Clear communication supports realistic decisions about the revised plan. The revised scope and available people need to be reflected in the work plan; a truthful account explains the constraint and resulting decisions.","source":{"anchor":"ksb-b7","guideSha256":"d5e4802223d7b6d3188731e9612e51c8f64a5b2d86c85188adaff8506b58ab9d","excerpt":"Describe a change in project scope, organisational direction or responsibilities and how you adapted the plan."},"id":"T47-E2-Q05"},{"ksb":"B7","objective":"Managing feedback during a pivot","prompt":"After a major scope change, stakeholders disagree about which features remain essential. Which response is appropriate?","options":[{"text":"Assume all stakeholders accepted a change because no one replied","why":"Silence is not necessarily evidence of shared understanding or agreement.","correct":false,"id":"A"},{"text":"Freeze every detail before checking whether the pivot serves its purpose","why":"Iterative feedback can help align the new approach with its intended use.","correct":false,"id":"B"},{"text":"Treat the loudest request as the entire new scope","why":"Requirements need a reasoned assessment of the affected needs and constraints.","correct":false,"id":"C"},{"text":"Make trade-offs and exclusions explicit","why":"Explicit decisions reduce surprise and support coordinated delivery.","correct":true,"id":"D"},{"text":"Clarify the revised decision needs and priorities","why":"Requirements need a reasoned assessment of the affected needs and constraints.","correct":true,"id":"E"},{"text":"Confirm the revised plan through the relevant decision-makers","why":"Silence is not necessarily evidence of shared understanding or agreement.","correct":true,"id":"F"},{"text":"Review feedback as the changed output develops","why":"Iterative feedback can help align the new approach with its intended use.","correct":true,"id":"G"},{"text":"Keep conflicting expectations undocumented","why":"Explicit decisions reduce surprise and support coordinated delivery.","correct":false,"id":"H"}],"answer":"Requirements need a reasoned assessment of the affected needs and constraints. Explicit decisions reduce surprise and support coordinated delivery. Silence is not necessarily evidence of shared understanding or agreement. Iterative feedback can help align the new approach with its intended use.","source":{"anchor":"ksb-b7","guideSha256":"d5e4802223d7b6d3188731e9612e51c8f64a5b2d86c85188adaff8506b58ab9d","excerpt":"Describe a change in project scope, organisational direction or responsibilities and how you adapted the plan."},"id":"T47-E2-Q06"},{"ksb":"B7","objective":"Explaining the contextual shift","prompt":"You need to demonstrate B7 from a project that changed organisational purpose. Which account is strongest?","options":[{"text":"Explain your personal adjustments and their rationale","why":"The behaviour needs evidence of how you adapted your own work.","correct":true,"id":"A"},{"text":"Claim every proposed change was implemented","why":"A truthful account distinguishes proposals, agreements and completed actions.","correct":false,"id":"B"},{"text":"Explain remaining limitations and lessons","why":"A useful explanation shows how the practical consequences were managed.","correct":true,"id":"C"},{"text":"Describe only a minor formatting problem","why":"A contextual shift concerns broader scope, goals or responsibilities rather than merely a small operational obstacle.","correct":false,"id":"D"},{"text":"Describe only management's decision with no account of your response","why":"The behaviour needs evidence of how you adapted your own work.","correct":false,"id":"E"},{"text":"Describe stakeholder feedback and the actual outcome","why":"A truthful account distinguishes proposals, agreements and completed actions.","correct":true,"id":"F"},{"text":"Present the pivot as effortless and omit material trade-offs","why":"A useful explanation shows how the practical consequences were managed.","correct":false,"id":"G"},{"text":"Compare the original and revised context clearly","why":"A contextual shift concerns broader scope, goals or responsibilities rather than merely a small operational obstacle.","correct":true,"id":"H"}],"answer":"A contextual shift concerns broader scope, goals or responsibilities rather than merely a small operational obstacle. The behaviour needs evidence of how you adapted your own work. A truthful account distinguishes proposals, agreements and completed actions. A useful explanation shows how the practical consequences were managed.","source":{"anchor":"ksb-b7","guideSha256":"d5e4802223d7b6d3188731e9612e51c8f64a5b2d86c85188adaff8506b58ab9d","excerpt":"Describe a change in project scope, organisational direction or responsibilities and how you adapted the plan."},"id":"T47-E2-Q07"},{"ksb":"B7","objective":"Expanded population","prompt":"A regional analysis is expanded to national coverage with different source definitions. Which adaptation is justified?","options":[{"text":"Explain any limits on comparison between regions","why":"Definition and collection differences can affect apparent regional variation.","correct":true,"id":"A"},{"text":"Involve relevant additional stakeholders","why":"Changed coverage can introduce new responsibilities and information needs.","correct":true,"id":"B"},{"text":"Revisit comparability, access and analytical assumptions","why":"A wider population and new sources can change the meaning of the analysis.","correct":true,"id":"C"},{"text":"Agree revised scope, timing and acceptance criteria","why":"The expanded task may need new checks and a different delivery plan.","correct":true,"id":"D"},{"text":"Present all differences as genuine performance effects","why":"Definition and collection differences can affect apparent regional variation.","correct":false,"id":"E"},{"text":"Append every national record without checking definitions","why":"A wider population and new sources can change the meaning of the analysis.","correct":false,"id":"F"},{"text":"Assume the original regional sponsor represents every national user","why":"Changed coverage can introduce new responsibilities and information needs.","correct":false,"id":"G"},{"text":"Retain the original regional checks as complete national validation","why":"The expanded task may need new checks and a different delivery plan.","correct":false,"id":"H"}],"answer":"A wider population and new sources can change the meaning of the analysis. The expanded task may need new checks and a different delivery plan. Changed coverage can introduce new responsibilities and information needs. Definition and collection differences can affect apparent regional variation.","source":{"anchor":"ksb-b7","guideSha256":"d5e4802223d7b6d3188731e9612e51c8f64a5b2d86c85188adaff8506b58ab9d","excerpt":"Describe a change in project scope, organisational direction or responsibilities and how you adapted the plan."},"id":"T47-E2-Q08"},{"ksb":"B7","objective":"Organisation-wide tool change","prompt":"The organisation retires the tool your project was built around. Which response is appropriate?","options":[{"text":"Describe the migration as complete once files open","why":"Opening files does not establish correct operation or sustainable support.","correct":false,"id":"A"},{"text":"Assess the approved replacement's capabilities and constraints","why":"Functional and analytical behaviour need checking in the replacement.","correct":true,"id":"B"},{"text":"Continue using the retired tool without addressing the applicable policy","why":"A contextual change can justify a new approach without rewriting the history of the earlier decision.","correct":false,"id":"C"},{"text":"Assume a similar interface guarantees equivalent calculations","why":"Functional and analytical behaviour need checking in the replacement.","correct":false,"id":"D"},{"text":"Communicate effects on scope and delivery","why":"Stakeholders need a realistic view of the changed platform context.","correct":true,"id":"E"},{"text":"Claim the change proves the original tool choice was always unreasonable","why":"A contextual change can justify a new approach without rewriting the history of the earlier decision.","correct":false,"id":"F"},{"text":"Conceal the dependency to preserve the old schedule","why":"Stakeholders need a realistic view of the changed platform context.","correct":false,"id":"G"},{"text":"Re-plan migration, validation and handover","why":"Opening files does not establish correct operation or sustainable support.","correct":true,"id":"H"}],"answer":"Functional and analytical behaviour need checking in the replacement. Opening files does not establish correct operation or sustainable support. Stakeholders need a realistic view of the changed platform context. A contextual change can justify a new approach without rewriting the history of the earlier decision.","source":{"anchor":"ksb-b7","guideSha256":"d5e4802223d7b6d3188731e9612e51c8f64a5b2d86c85188adaff8506b58ab9d","excerpt":"Describe a change in project scope, organisational direction or responsibilities and how you adapted the plan."},"id":"T47-E2-Q09"},{"ksb":"B7","objective":"Policy-driven redesign","prompt":"A new organisational rule prevents the planned person-level extract. Which pivot is defensible?","options":[{"text":"Revisit methods, validation and communication","why":"A different grain or scope can require different methods and checks.","correct":true,"id":"A"},{"text":"Agree what the reduced detail can and cannot support","why":"Changing detail can limit the analyses and interpretations available.","correct":true,"id":"B"},{"text":"Assess whether approved aggregates can answer a revised question","why":"A policy change needs to be addressed through authorised handling rather than bypassed.","correct":true,"id":"C"},{"text":"Claim aggregate data supports every original individual-level conclusion","why":"Changing detail can limit the analyses and interpretations available.","correct":false,"id":"D"},{"text":"Report the original individual-level analysis as completed","why":"The change affects both truthful reporting and the agreed project purpose.","correct":false,"id":"E"},{"text":"Assume a restrictive policy removes the need for stakeholder discussion","why":"The change affects both truthful reporting and the agreed project purpose.","correct":false,"id":"F"},{"text":"Treat the new input as analytically identical without checking","why":"A different grain or scope can require different methods and checks.","correct":false,"id":"G"},{"text":"Use an old unrestricted copy to preserve the original design","why":"A policy change needs to be addressed through authorised handling rather than bypassed.","correct":false,"id":"H"}],"answer":"A policy change needs to be addressed through authorised handling rather than bypassed. Changing detail can limit the analyses and interpretations available. A different grain or scope can require different methods and checks. The change affects both truthful reporting and the agreed project purpose.","source":{"anchor":"ksb-b7","guideSha256":"d5e4802223d7b6d3188731e9612e51c8f64a5b2d86c85188adaff8506b58ab9d","excerpt":"Describe a change in project scope, organisational direction or responsibilities and how you adapted the plan."},"id":"T47-E2-Q10"}]},{"id":"T48","title":"A service dashboard under review","description":"Connect requirements, governance, joins, quality and communication.","questions":[{"ksb":"K9","objective":"Dashboard decision","prompt":"In this fictional service-dashboard project, the sponsor asks for a weekly exception view but has not defined which cases require action. What should the analyst establish?","options":[{"text":"The decision owner and action triggered by an exception","why":"The dashboard needs an operational purpose and rule before its visual styling is chosen.","correct":true,"id":"A"},{"text":"The chart colour before defining the exception","why":"The dashboard needs an operational purpose and rule before its visual styling is chosen.","correct":false,"id":"B"},{"text":"A population inferred solely from the first available export","why":"The requirement should define the population rather than inherit an accidental data boundary.","correct":false,"id":"C"},{"text":"Acceptance checks for finding and interpreting an exception","why":"A published page does not establish that the intended decision task is supported.","correct":true,"id":"D"},{"text":"Access and delivery dependencies","why":"A feasible brief accounts for the data, permissions and work required.","correct":true,"id":"E"},{"text":"A promise of every requested filter before checking feasibility","why":"A feasible brief accounts for the data, permissions and work required.","correct":false,"id":"F"},{"text":"The eligible cases, period and exception definition","why":"The requirement should define the population rather than inherit an accidental data boundary.","correct":true,"id":"G"},{"text":"Completion defined only as publishing a working URL","why":"A published page does not establish that the intended decision task is supported.","correct":false,"id":"H"}],"answer":"The dashboard needs an operational purpose and rule before its visual styling is chosen. The requirement should define the population rather than inherit an accidental data boundary. A published page does not establish that the intended decision task is supported. A feasible brief accounts for the data, permissions and work required.","source":{"anchor":"ksb-k9","guideSha256":"eb674e8d4cdda55c9d3afa802f91f1308dabfc550c738417443a9c6b3c08aad3","excerpt":"Requirements describe the decision to support, the intended users, necessary outputs, constraints and what success looks like."},"id":"T48-E2-Q01"},{"ksb":"K8","objective":"Missing-date comparison","prompt":"The dashboard extract has 1,000 completed cases; 50 lack closure dates, with 40 of those in one service. Which quality conclusions are justified?","options":[{"text":"Infer the missing cases are a random sample from their absence alone","why":"The subgroup denominator and missingness mechanism are not supplied by these totals.","correct":false,"id":"A"},{"text":"Treat every missing closure date as same-day completion","why":"Missing timing does not establish a zero-duration completed case.","correct":false,"id":"B"},{"text":"The concentration may distort that service's comparison","why":"Group-specific missingness can be material even when the overall proportion is modest.","correct":true,"id":"C"},{"text":"Infer the affected service's exact completeness without knowing its case count","why":"The subgroup denominator and missingness mechanism are not supplied by these totals.","correct":false,"id":"D"},{"text":"Overall closure-date completeness is 95%","why":"There are 950 populated closure dates out of 1,000 expected values.","correct":true,"id":"E"},{"text":"Investigate the missing dates before choosing treatment","why":"Missing timing does not establish a zero-duration completed case.","correct":true,"id":"F"},{"text":"A small overall missing rate proves every service comparison is safe","why":"Group-specific missingness can be material even when the overall proportion is modest.","correct":false,"id":"G"},{"text":"Overall closure-date completeness is 50%","why":"There are 950 populated closure dates out of 1,000 expected values.","correct":false,"id":"H"}],"answer":"There are 950 populated closure dates out of 1,000 expected values. Group-specific missingness can be material even when the overall proportion is modest. Missing timing does not establish a zero-duration completed case. The subgroup denominator and missingness mechanism are not supplied by these totals.","source":{"anchor":"ksb-k8","guideSha256":"fc36fd1d312de49da019f804e76b601292749db78dee939b5d15f83d46f681e6","excerpt":"Quality means suitability for the intended decision."},"id":"T48-E2-Q02"},{"ksb":"S8","objective":"Reference merge","prompt":"A service target varies by month. The dashboard joins requests to the target file using only service code, producing extra rows. Which actions address the specific problem?","options":[{"text":"Average targets across months without agreement","why":"Neither an unsupported average nor hiding the period repairs the underlying matching rule.","correct":false,"id":"A"},{"text":"Check one authoritative target per service-month","why":"File order does not establish which monthly target applies.","correct":true,"id":"B"},{"text":"Reconcile request identities and totals after the corrected merge","why":"The repaired data needs verification beyond its chart appearance.","correct":true,"id":"C"},{"text":"Include the appropriate month in the intended matching key","why":"The reference grain is service-month, while repeated service codes in request records can be valid.","correct":true,"id":"D"},{"text":"Remove the month field from the final output to resolve the mismatch","why":"Neither an unsupported average nor hiding the period repairs the underlying matching rule.","correct":false,"id":"E"},{"text":"Deduplicate requests merely because their service repeats","why":"The reference grain is service-month, while repeated service codes in request records can be valid.","correct":false,"id":"F"},{"text":"Check only whether the extra rows disappear visually","why":"The repaired data needs verification beyond its chart appearance.","correct":false,"id":"G"},{"text":"Choose the first target row as the rule for every month","why":"File order does not establish which monthly target applies.","correct":false,"id":"H"}],"answer":"The reference grain is service-month, while repeated service codes in request records can be valid. File order does not establish which monthly target applies. The repaired data needs verification beyond its chart appearance. Neither an unsupported average nor hiding the period repairs the underlying matching rule.","source":{"anchor":"ksb-s8","guideSha256":"0f5cddb86161986b79351977142757eead70691fc156a7d038e573f11ffcd428","excerpt":"Demonstrate a repeatable join in an appropriate tool, with explicit keys, grain and validation."},"id":"T48-E2-Q03"},{"ksb":"K10","objective":"Preserving unmatched cases","prompt":"The corrected dashboard must retain cases whose target is unavailable. Which join and interpretation choices meet that need?","options":[{"text":"Use an inner join and still describe the output as every case","why":"An inner join drops cases without a target match.","correct":false,"id":"A"},{"text":"Use an appropriate left join from the cases","why":"An inner join drops cases without a target match.","correct":true,"id":"B"},{"text":"Assume a left join guarantees one row per source case","why":"Multiple right-side matches can still multiply retained case rows.","correct":false,"id":"C"},{"text":"Explain unmatched coverage in the report","why":"Failure against a target cannot be established when the relevant target is unknown.","correct":true,"id":"D"},{"text":"Replace every unmatched target with zero","why":"An unknown target does not establish that a case was required to finish immediately.","correct":false,"id":"E"},{"text":"Check that reference multiplicity does not inflate case rows","why":"Multiple right-side matches can still multiply retained case rows.","correct":true,"id":"F"},{"text":"Label unmatched cases as verified target failures","why":"Failure against a target cannot be established when the relevant target is unknown.","correct":false,"id":"G"},{"text":"Keep missing targets distinct from zero-day targets","why":"An unknown target does not establish that a case was required to finish immediately.","correct":true,"id":"H"}],"answer":"An inner join drops cases without a target match. An unknown target does not establish that a case was required to finish immediately. Multiple right-side matches can still multiply retained case rows. Failure against a target cannot be established when the relevant target is unknown.","source":{"anchor":"ksb-k10","guideSha256":"789a8030c85d44e631a391ddb89038ecb496d54b8e9edd6edf349cc51dc3808b","excerpt":"A primary key uniquely identifies a row and cannot be NULL; a foreign key refers to a key in a related table; a composite key uses more than one field."},"id":"T48-E2-Q04"},{"ksb":"S6","objective":"Verified correction","prompt":"The target owner supplies an approved correction for conflicting service-month entries. What should the analyst do before using the revised dashboard?","options":[{"text":"Apply the agreed mapping through the recorded transformation","why":"The correction belongs in a traceable data process rather than an unsupported display override.","correct":true,"id":"A"},{"text":"Alter the displayed rate manually to match the owner's expectation","why":"The correction belongs in a traceable data process rather than an unsupported display override.","correct":false,"id":"B"},{"text":"Validate only the single example shown in the correction email","why":"A change can affect other records or calculations.","correct":false,"id":"C"},{"text":"Check affected cases and important totals","why":"Approval establishes authority for the rule, not that every dependent output has been checked.","correct":true,"id":"D"},{"text":"Delete the original issue record after the chart improves","why":"The correction should remain explainable and auditable.","correct":false,"id":"E"},{"text":"Record the issue, action and remaining limits","why":"The correction should remain explainable and auditable.","correct":true,"id":"F"},{"text":"Treat the owner's approval as completed output validation","why":"Approval establishes authority for the rule, not that every dependent output has been checked.","correct":false,"id":"G"},{"text":"Review unaffected services for unintended effects","why":"A change can affect other records or calculations.","correct":true,"id":"H"}],"answer":"The correction belongs in a traceable data process rather than an unsupported display override. Approval establishes authority for the rule, not that every dependent output has been checked. A change can affect other records or calculations. The correction should remain explainable and auditable.","source":{"anchor":"ksb-s6","guideSha256":"dc73f26172b8e4a54be65d1401e4ce48334bb00e7eafdface7d2f4064df7d492","excerpt":"Demonstrate a complete issue-handling loop: detect, measure, assess impact, investigate, mitigate or escalate, resolve where authorised, and validate."},"id":"T48-E2-Q05"},{"ksb":"S5","objective":"Operational presentation","prompt":"Managers misread the weekly dashboard's red and green dots and cannot see which region is selected. Which changes address the observed usability problems?","options":[{"text":"Count a new colour palette as proof both problems are resolved","why":"Actual user interpretation should verify the targeted changes.","correct":false,"id":"A"},{"text":"Remove the regional filter label but retain its effect","why":"Hiding context and enlarging charts do not establish correct interpretation or complete accessibility.","correct":false,"id":"B"},{"text":"Retest the relevant interpretation task with users","why":"Actual user interpretation should verify the targeted changes.","correct":true,"id":"C"},{"text":"Keep the region only in a hover tip absent from screenshots","why":"The chosen population needs to remain visible in ordinary and exported use.","correct":false,"id":"D"},{"text":"Show the active region alongside the measures","why":"The chosen population needs to remain visible in ordinary and exported use.","correct":true,"id":"E"},{"text":"Change shades while retaining colour as the only identifier","why":"Additional cues address the difficulty distinguishing status meanings.","correct":false,"id":"F"},{"text":"Describe the design as accessible solely because it uses large charts","why":"Hiding context and enlarging charts do not establish correct interpretation or complete accessibility.","correct":false,"id":"G"},{"text":"Add meaningful status labels or non-colour distinctions","why":"Additional cues address the difficulty distinguishing status meanings.","correct":true,"id":"H"}],"answer":"Additional cues address the difficulty distinguishing status meanings. The chosen population needs to remain visible in ordinary and exported use. Actual user interpretation should verify the targeted changes. Hiding context and enlarging charts do not establish correct interpretation or complete accessibility.","source":{"anchor":"ksb-s5","guideSha256":"ae3dee68ad2f3e625ff15c4d92fe7dea8079d619397bfe07497e53d6af6fe64a","excerpt":"Connect each design choice to a stakeholder task."},"id":"T48-E2-Q06"},{"ksb":"S14","objective":"Feedback themes","prompt":"The dashboard team codes 30 comments into 45 theme assignments, allowing multiple themes per comment. Which display choices and conclusions are justified?","options":[{"text":"Use the two denominators interchangeably under one label","why":"The chosen denominator changes the meaning of the percentage.","correct":false,"id":"A"},{"text":"Treat theme IDs as a continuous severity scale","why":"Numeric category identifiers do not create a measurement scale.","correct":false,"id":"B"},{"text":"State whether percentages use comments or assignments","why":"The chosen denominator changes the meaning of the percentage.","correct":true,"id":"C"},{"text":"Describe the 45 assignments as 45 distinct respondents","why":"Assignments can exceed comments and do not establish a distinct respondent count.","correct":false,"id":"D"},{"text":"Present the observed themes as the exact opinion of every service user","why":"The collection and coding process limit the claims supported by the sample.","correct":false,"id":"E"},{"text":"Describe themes as qualitative interpretations summarised numerically","why":"Numeric category identifiers do not create a measurement scale.","correct":true,"id":"F"},{"text":"Show theme counts with an explicit coding explanation","why":"Assignments can exceed comments and do not establish a distinct respondent count.","correct":true,"id":"G"},{"text":"Explain limits of the feedback sample","why":"The collection and coding process limit the claims supported by the sample.","correct":true,"id":"H"}],"answer":"Assignments can exceed comments and do not establish a distinct respondent count. The chosen denominator changes the meaning of the percentage. Numeric category identifiers do not create a measurement scale. The collection and coding process limit the claims supported by the sample.","source":{"anchor":"ksb-s14","guideSha256":"fe8ae3c33cc1c8e2bd105b901a97f94b26b72e1bf2336b438fdcac2217923fbd","excerpt":"Quantitative data measures quantities such as counts or durations."},"id":"T48-E2-Q07"},{"ksb":"S12","objective":"Two-part briefing","prompt":"The service manager needs the dashboard's decision implications; the data engineer needs to review the target merge. Which communication plan fits?","options":[{"text":"Record genuine feedback and resulting changes","why":"Distinct stakeholder evidence concerns the actual people or roles involved, not attachment count.","correct":true,"id":"A"},{"text":"Remove every caveat because the manager is non-technical","why":"Audience adaptation should preserve uncertainty relevant to the decision.","correct":false,"id":"B"},{"text":"Describe the whole team's communication as your own","why":"Delivery and teamwork need accurate evidence of use and personal contribution.","correct":false,"id":"C"},{"text":"Send only the same unexplained headline chart to both","why":"Technical review needs methodological detail tailored to the engineer's role.","correct":false,"id":"D"},{"text":"Explain findings and material limitations to the manager","why":"Audience adaptation should preserve uncertainty relevant to the decision.","correct":true,"id":"E"},{"text":"Claim adoption because the report was emailed","why":"Delivery and teamwork need accurate evidence of use and personal contribution.","correct":false,"id":"F"},{"text":"Share relevant keys, transformations and checks with the engineer","why":"Technical review needs methodological detail tailored to the engineer's role.","correct":true,"id":"G"},{"text":"Count two attachments to one person as two stakeholders","why":"Distinct stakeholder evidence concerns the actual people or roles involved, not attachment count.","correct":false,"id":"H"}],"answer":"Audience adaptation should preserve uncertainty relevant to the decision. Technical review needs methodological detail tailored to the engineer's role. Distinct stakeholder evidence concerns the actual people or roles involved, not attachment count. Delivery and teamwork need accurate evidence of use and personal contribution.","source":{"anchor":"ksb-s12","guideSha256":"3eb2f4c5da12f2a05c97da6f15657d048685f3b46342a8ed73abb499f2680160","excerpt":"Show communication with at least two distinct stakeholders as requested in the supplied preparation guide, and cover all relevant stakeholders for the work."},"id":"T48-E2-Q08"},{"ksb":"B5","objective":"Recurring target defect","prompt":"Each month a manual reference upload permits two targets for the same service-month. Which response addresses the recurring cause?","options":[{"text":"Document responsibility for the preventive control","why":"Ownership must follow the agreed organisational responsibility.","correct":true,"id":"A"},{"text":"Reproduce how conflicting keys enter and affect the join","why":"The observed mechanism concerns the reference process and its downstream relationship.","correct":true,"id":"B"},{"text":"Diagnose the chart as the cause solely because it displays the error","why":"The observed mechanism concerns the reference process and its downstream relationship.","correct":false,"id":"C"},{"text":"Declare permanent prevention from one clean refresh","why":"Prevention needs follow-up evidence under later relevant conditions.","correct":false,"id":"D"},{"text":"Delete repeated output rows manually every month as the whole solution","why":"A recurring output repair leaves the source mechanism unaddressed.","correct":false,"id":"E"},{"text":"Assume the person who noticed the issue automatically owns the source system","why":"Ownership must follow the agreed organisational responsibility.","correct":false,"id":"F"},{"text":"Verify the current repair and monitor later uploads","why":"Prevention needs follow-up evidence under later relevant conditions.","correct":true,"id":"G"},{"text":"Agree a suitable uniqueness or exception control with the owner","why":"A recurring output repair leaves the source mechanism unaddressed.","correct":true,"id":"H"}],"answer":"The observed mechanism concerns the reference process and its downstream relationship. A recurring output repair leaves the source mechanism unaddressed. Prevention needs follow-up evidence under later relevant conditions. Ownership must follow the agreed organisational responsibility.","source":{"anchor":"ksb-b5","guideSha256":"dd78340b0eb1bf21bc522276c8df9a6086e26a70149be0507bb287ab4145c106","excerpt":"Separate the visible symptom, the immediate mechanism and the underlying cause."},"id":"T48-E2-Q09"},{"ksb":"B4","objective":"Conflicting headline","prompt":"After correction, two dashboards still disagree. One includes withdrawn cases and the other excludes them. Which reasoning is justified?","options":[{"text":"Explain any remaining legitimate difference","why":"Different valid definitions can yield different totals and need clear explanation.","correct":true,"id":"A"},{"text":"Force identical values even when the measures intentionally differ","why":"Different valid definitions can yield different totals and need clear explanation.","correct":false,"id":"B"},{"text":"Reconcile the population definitions before comparing totals","why":"Averaging does not resolve their different meanings.","correct":true,"id":"C"},{"text":"Check which definition meets the agreed requirement","why":"The requirement, not preferred magnitude, should determine the calculation.","correct":true,"id":"D"},{"text":"Average the two totals to produce a neutral answer","why":"Averaging does not resolve their different meanings.","correct":false,"id":"E"},{"text":"Revise the earlier hypothesis if the join is no longer the cause","why":"Reasoning should follow current evidence rather than remain fixed on an earlier cause.","correct":true,"id":"F"},{"text":"Continue deleting rows because the first problem involved duplicates","why":"Reasoning should follow current evidence rather than remain fixed on an earlier cause.","correct":false,"id":"G"},{"text":"Choose the larger total to avoid understating activity","why":"The requirement, not preferred magnitude, should determine the calculation.","correct":false,"id":"H"}],"answer":"Averaging does not resolve their different meanings. The requirement, not preferred magnitude, should determine the calculation. Different valid definitions can yield different totals and need clear explanation. Reasoning should follow current evidence rather than remain fixed on an earlier cause.","source":{"anchor":"ksb-b4","guideSha256":"19544c61d4657ced69a0de9a91c60998a3caac5acfd7f29fa94d863d5f1dfbb2","excerpt":"Show how you independently structured an uncertain problem, formed explanations, chose tests and revised your judgement from evidence."},"id":"T48-E2-Q10"}]},{"id":"T49","title":"Forecasting a capacity decision","description":"Connect statistics, prediction, ethical interpretation and feasible action.","questions":[{"ksb":"K13","objective":"Capacity summaries","prompt":"A fictional capacity review records five completed-case durations: 3, 4, 4, 7 and 12 days. Which summaries are correct?","options":[{"text":"The mean is 7 days","why":"The five durations total 30, giving an arithmetic mean of 6.","correct":false,"id":"A"},{"text":"The mean is 6 days","why":"The five durations total 30, giving an arithmetic mean of 6.","correct":true,"id":"B"},{"text":"The median is 4 days","why":"The middle ordered value is 4.","correct":true,"id":"C"},{"text":"The largest value alone proves a data-entry error","why":"An average does not establish the most common duration, and an extreme value needs investigation before being called erroneous.","correct":false,"id":"D"},{"text":"The mode is 12 days","why":"Four is the most frequent observed value.","correct":false,"id":"E"},{"text":"The mean shows that most cases took six days","why":"An average does not establish the most common duration, and an extreme value needs investigation before being called erroneous.","correct":false,"id":"F"},{"text":"The mode is 4 days","why":"Four is the most frequent observed value.","correct":true,"id":"G"},{"text":"The median is 6 days","why":"The middle ordered value is 4.","correct":false,"id":"H"}],"answer":"The five durations total 30, giving an arithmetic mean of 6. The middle ordered value is 4. Four is the most frequent observed value. An average does not establish the most common duration, and an extreme value needs investigation before being called erroneous.","source":{"anchor":"ksb-k13","guideSha256":"04d385bb1be74eba3f31f9339493e5aa11dea86835de979e56753f3e109018db","excerpt":"Descriptive statistics summarise observed data; inferential statistics use a sample and assumptions to reason about a wider process or population."},"id":"T49-E2-Q01"},{"ksb":"S10","objective":"Planned threshold","prompt":"In the capacity project, a valid planned test gives p = 0.04. The team pre-specified alpha = 0.01. Which interpretation is justified?","options":[{"text":"Change alpha to 0.05 after seeing the result and describe it as the original plan","why":"Post-hoc revision should not be represented as the pre-specified decision rule.","correct":false,"id":"A"},{"text":"Reject because every p-value below 0.05 must be significant for this plan","why":"The specified threshold is 0.01, and 0.04 exceeds it.","correct":false,"id":"B"},{"text":"State that the null has a 4% probability of being true","why":"A p-value is not a posterior probability of the hypothesis.","correct":false,"id":"C"},{"text":"Explain the p-value conditional on the null and assumptions","why":"A p-value is not a posterior probability of the hypothesis.","correct":true,"id":"D"},{"text":"State that non-rejection proves the population difference is exactly zero","why":"Non-rejection does not establish exact equality.","correct":false,"id":"E"},{"text":"Report the estimated effect and uncertainty","why":"Non-rejection does not establish exact equality.","correct":true,"id":"F"},{"text":"Retain the planned threshold when explaining the result","why":"Post-hoc revision should not be represented as the pre-specified decision rule.","correct":true,"id":"G"},{"text":"Do not reject the null at the planned threshold","why":"The specified threshold is 0.01, and 0.04 exceeds it.","correct":true,"id":"H"}],"answer":"The specified threshold is 0.01, and 0.04 exceeds it. Non-rejection does not establish exact equality. A p-value is not a posterior probability of the hypothesis. Post-hoc revision should not be represented as the pre-specified decision rule.","source":{"anchor":"ksb-s10","guideSha256":"c42a163b39508febe898efed0feb19bdc5dadb606e898701905c94e865897acc","excerpt":"Start with EDA: check shape, data types, missingness, duplicates, distributions, outliers, groups and possible sampling bias."},"id":"T49-E2-Q02"},{"ksb":"S11","objective":"Future information","prompt":"The breach model uses a field completed only when a case closes, but predictions are needed when cases open. Which corrections are necessary?","options":[{"text":"Exclude or replace that field with eligible opening-time information","why":"The field is unavailable at the required prediction time and leaks future information.","correct":true,"id":"A"},{"text":"Treat leakage as acceptable when the report includes a caveat","why":"Feature availability must match the actual prediction time. A short lag or caveat does not make future case information available when the case opens.","correct":false,"id":"B"},{"text":"Lag the closure-only field by one day and assume it is then available at case opening","why":"Feature availability must match the actual prediction time. A short lag or caveat does not make future case information available when the case opens.","correct":false,"id":"C"},{"text":"Keep it because the retrospective score is strong","why":"The field is unavailable at the required prediction time and leaks future information.","correct":false,"id":"D"},{"text":"Reuse the leaking model's score as the corrected model's validated result","why":"Changing the model inputs requires an appropriate new evaluation.","correct":false,"id":"E"},{"text":"Re-evaluate the corrected workflow on suitable unseen cases","why":"Changing the model inputs requires an appropriate new evaluation.","correct":true,"id":"F"},{"text":"Define and document the prediction point","why":"Feature eligibility depends on the actual timing of the intended prediction.","correct":true,"id":"G"},{"text":"Assume every historical column is available at every operational stage","why":"Feature eligibility depends on the actual timing of the intended prediction.","correct":false,"id":"H"}],"answer":"The field is unavailable at the required prediction time and leaks future information. Changing the model inputs requires an appropriate new evaluation. Feature eligibility depends on the actual timing of the intended prediction. Feature availability must match the actual prediction time. A short lag or caveat does not make future case information available when the case opens.","source":{"anchor":"ksb-s11","guideSha256":"6cf9f35febad9dfa76eb76a27e7eeb97d5312845c45dea04f5b5a8390f488a54","excerpt":"Demonstrate a connected descriptive, predictive and prescriptive workflow."},"id":"T49-E2-Q03"},{"ksb":"S13","objective":"Common holdout","prompt":"Weekly actual demand is [10, 14]. Candidate forecasts are [12, 12], and baseline forecasts are [10, 10]. Which comparison is correct?","options":[{"text":"Baseline RMSE is sqrt(8), about 2.828","why":"Baseline squared errors are 0 and 16, whose mean is 8 before taking the root.","correct":true,"id":"A"},{"text":"Further periods are needed for a stronger performance assessment","why":"The small comparison supports a limited result rather than a universal seasonal claim.","correct":true,"id":"B"},{"text":"Baseline RMSE is 2, its mean absolute error","why":"Baseline squared errors are 0 and 16, whose mean is 8 before taking the root.","correct":false,"id":"C"},{"text":"Candidate RMSE is 0 because its signed errors cancel","why":"RMSE squares errors before averaging, so cancellation of signed errors does not produce zero.","correct":false,"id":"D"},{"text":"Candidate RMSE is 2","why":"RMSE squares errors before averaging, so cancellation of signed errors does not produce zero.","correct":true,"id":"E"},{"text":"The baseline wins overall because one week is predicted exactly","why":"The common-holdout metric uses both observations.","correct":false,"id":"F"},{"text":"The candidate has lower RMSE on these same weeks","why":"The common-holdout metric uses both observations.","correct":true,"id":"G"},{"text":"Two weeks prove the candidate is best in every season","why":"The small comparison supports a limited result rather than a universal seasonal claim.","correct":false,"id":"H"}],"answer":"RMSE squares errors before averaging, so cancellation of signed errors does not produce zero. Baseline squared errors are 0 and 16, whose mean is 8 before taking the root. The common-holdout metric uses both observations. The small comparison supports a limited result rather than a universal seasonal claim.","source":{"anchor":"ksb-s13","guideSha256":"46cd9f000fc581e86430af6ad25dc0a9ed1c49d6ecee41240ee5c9cf42272384","excerpt":"Define a forecast target, frequency, observation window and horizon."},"id":"T49-E2-Q04"},{"ksb":"K14","objective":"Feasible action","prompt":"Next week's forecast is 120 cases and current capacity is 100. An approved temporary rota can add 20 next week at a known cost; training adds capacity only next month. Which recommendations are defensible?","options":[{"text":"Claim the training option was implemented merely because it was discussed","why":"Predictive information does not establish an intervention effect or evidence of completed action.","correct":false,"id":"A"},{"text":"Recommend next month's training as if it supplies next week's capacity","why":"The proposed action must fit the decision's timing.","correct":false,"id":"B"},{"text":"Select an option solely because it has the most attractive forecast chart","why":"Prescriptive reasoning needs objectives, resources and constraints beyond visual presentation.","correct":false,"id":"C"},{"text":"Treat 120 cases as a guaranteed future observation","why":"A forecast is uncertain and should not be presented as known demand.","correct":false,"id":"D"},{"text":"Infer that the forecast proves the causal effect of the rota","why":"Predictive information does not establish an intervention effect or evidence of completed action.","correct":false,"id":"E"},{"text":"Compare feasible alternatives under the actual constraints","why":"Prescriptive reasoning needs objectives, resources and constraints beyond visual presentation.","correct":true,"id":"F"},{"text":"Explain forecast uncertainty and a review arrangement","why":"A forecast is uncertain and should not be presented as known demand.","correct":true,"id":"G"},{"text":"Consider the temporary rota against service benefit and cost","why":"The proposed action must fit the decision's timing.","correct":true,"id":"H"}],"answer":"The proposed action must fit the decision's timing. A forecast is uncertain and should not be presented as known demand. Prescriptive reasoning needs objectives, resources and constraints beyond visual presentation. Predictive information does not establish an intervention effect or evidence of completed action.","source":{"anchor":"ksb-k14","guideSha256":"5ce7abb6ad5d1959f0b2f32856f8152bd2020ed39cddc5e30c12ee30fcafed91","excerpt":"Descriptive analytics explains observed results: “What happened?” Predictive analytics estimates unknown or future outcomes with uncertainty: “What might happen?” Prescriptive analytics recommends actions using evidence, objectives and constraints: “What should we do?” In a fictional service project, descriptive analysis summarises completed requests and waiting-time distributions."},"id":"T49-E2-Q05"},{"ksb":"K15","objective":"Coverage bias","prompt":"The capacity model uses online requests only, while some users can access the service only by telephone. Which ethical analytical response is justified?","options":[{"text":"Investigate appropriate supplementary evidence or bounded use","why":"A missing group is not evidence that its needs are zero.","correct":true,"id":"A"},{"text":"Consider the impact of the allocation on affected groups","why":"Predictive accuracy within one channel does not establish fair coverage or outcomes across groups.","correct":true,"id":"B"},{"text":"Treat good overall online prediction as proof of fair allocation for everyone","why":"Predictive accuracy within one channel does not establish fair coverage or outcomes across groups.","correct":false,"id":"C"},{"text":"Assess whose demand is missing from the training source","why":"The access channel can exclude people who still need the service.","correct":true,"id":"D"},{"text":"Present the model as representing every user without qualification","why":"The model's scope should reflect the population actually observed.","correct":false,"id":"E"},{"text":"Treat absent online records as proof of no demand","why":"The access channel can exclude people who still need the service.","correct":false,"id":"F"},{"text":"Explain the coverage limit to decision-makers","why":"The model's scope should reflect the population actually observed.","correct":true,"id":"G"},{"text":"Allocate zero capacity to telephone users solely from their absence online","why":"A missing group is not evidence that its needs are zero.","correct":false,"id":"H"}],"answer":"The access channel can exclude people who still need the service. The model's scope should reflect the population actually observed. A missing group is not evidence that its needs are zero. Predictive accuracy within one channel does not establish fair coverage or outcomes across groups.","source":{"anchor":"ksb-k15","guideSha256":"1d702236151e0909ddb381cdf3973f8b40cbe3601a180e66940fe44712f81256","excerpt":"Ethics asks whether data use is appropriate and fair, including where a use might be legally permitted."},"id":"T49-E2-Q06"},{"ksb":"S15","objective":"Tool fit","prompt":"The organisation permits SQL for extraction and a supported modelling environment for the capacity analysis. A personal tool lacks approved access. Which selection is justified?","options":[{"text":"Use feasible approved capabilities to meet the actual analytical need","why":"Tool preference does not justify bypassing the approved handling environment.","correct":true,"id":"A"},{"text":"Select the modelling tool solely from source connectivity without checking validation and handover needs","why":"Connectivity is necessary but does not establish complete analytical, deployment or support suitability.","correct":false,"id":"B"},{"text":"Claim a tool was applied because it appeared in the comparison table","why":"Considering a tool and actually using it are different forms of evidence.","correct":false,"id":"C"},{"text":"Explain each selected tool's actual role","why":"Considering a tool and actually using it are different forms of evidence.","correct":true,"id":"D"},{"text":"Compare reproducibility, model capability and team support","why":"Practical fit includes capability and ongoing operation as well as direct cost.","correct":true,"id":"E"},{"text":"Choose only by the lowest advertised licence price","why":"Practical fit includes capability and ongoing operation as well as direct cost.","correct":false,"id":"F"},{"text":"Export restricted records personally to preserve a preferred interface","why":"Tool preference does not justify bypassing the approved handling environment.","correct":false,"id":"G"},{"text":"Treat source connectivity as proof every modelling assumption is met","why":"Connectivity is necessary but does not establish complete analytical, deployment or support suitability.","correct":false,"id":"H"}],"answer":"Tool preference does not justify bypassing the approved handling environment. Practical fit includes capability and ongoing operation as well as direct cost. Considering a tool and actually using it are different forms of evidence. Connectivity is necessary but does not establish complete analytical, deployment or support suitability.","source":{"anchor":"ksb-s15","guideSha256":"57328e157ecc1d18b4913049441798285a61136023fe24c5a86de23aca366ccb","excerpt":"Show the decision process and then show that you applied the selected tool."},"id":"T49-E2-Q07"},{"ksb":"B6","objective":"Unfavourable validation","prompt":"The first capacity model performs worse than the baseline on the held-out period. Which response demonstrates resilience?","options":[{"text":"State only that the task was difficult","why":"A specific lesson shows how the challenge improved later judgement or action.","correct":false,"id":"A"},{"text":"Investigate specific limitations and a realistic next step","why":"Further development needs an appropriate evaluation strategy and honest treatment of reused evidence.","correct":true,"id":"B"},{"text":"Omit the baseline to present the model as successful","why":"A meaningful comparison should not be hidden to protect the appearance of success.","correct":false,"id":"C"},{"text":"Report the result and its evaluation conditions honestly","why":"A meaningful comparison should not be hidden to protect the appearance of success.","correct":true,"id":"D"},{"text":"Deploy complexity solely because it required more effort","why":"Development effort does not establish a better outcome.","correct":false,"id":"E"},{"text":"Consider a justified simpler approach if it meets the need","why":"Development effort does not establish a better outcome.","correct":true,"id":"F"},{"text":"Record what the evidence changed in your future practice","why":"A specific lesson shows how the challenge improved later judgement or action.","correct":true,"id":"G"},{"text":"Repeat tuning on the final holdout while calling every trial independent","why":"Further development needs an appropriate evaluation strategy and honest treatment of reused evidence.","correct":false,"id":"H"}],"answer":"A meaningful comparison should not be hidden to protect the appearance of success. Further development needs an appropriate evaluation strategy and honest treatment of reused evidence. Development effort does not establish a better outcome. A specific lesson shows how the challenge improved later judgement or action.","source":{"anchor":"ksb-b6","guideSha256":"a26a2f78cc1df19af5ec0ad9d32ce26fa6440cfc9aedf519f4e1bf1b739babb3","excerpt":"Give a specific challenge and explain a constructive response: reassess, seek appropriate support, break work into manageable steps, use feedback and maintain quality."},"id":"T49-E2-Q08"},{"ksb":"S7","objective":"Revised acceptance","prompt":"Stakeholders clarify that next week's decision concerns only one service and needs a capacity range rather than a single unqualified figure. Which implementation changes are appropriate?","options":[{"text":"Retain the organisation-wide scope without agreement","why":"The output needs to match the revised decision population.","correct":false,"id":"A"},{"text":"Change only the report title while keeping the old calculations","why":"A revised scope can affect inputs, calculations and interpretation.","correct":false,"id":"B"},{"text":"Update acceptance checks and the final explanation","why":"A revised scope can affect inputs, calculations and interpretation.","correct":true,"id":"C"},{"text":"Confirm the service population and horizon","why":"The output needs to match the revised decision population.","correct":true,"id":"D"},{"text":"Provide an appropriate account of uncertainty","why":"A range or uncertainty explanation should reflect the evidence rather than create certainty.","correct":true,"id":"E"},{"text":"Assume clarification can never affect the work required","why":"Requirement changes can alter effort and need explicit management.","correct":false,"id":"F"},{"text":"Agree any implications for delivery and maintenance","why":"Requirement changes can alter effort and need explicit management.","correct":true,"id":"G"},{"text":"Label the point forecast as a guaranteed capacity requirement","why":"A range or uncertainty explanation should reflect the evidence rather than create certainty.","correct":false,"id":"H"}],"answer":"The output needs to match the revised decision population. A range or uncertainty explanation should reflect the evidence rather than create certainty. A revised scope can affect inputs, calculations and interpretation. Requirement changes can alter effort and need explicit management.","source":{"anchor":"ksb-s7","guideSha256":"762c5d5a314f38868448a38aed918ae5c309770463d456b02ece5c88cba6bd1f","excerpt":"Show a chain from a stated need to planned method, output and acceptance check."},"id":"T49-E2-Q09"},{"ksb":"B7","objective":"Operational pivot","prompt":"The capacity project changes from a long-term expansion study to an urgent backlog response. Which adaptation fits the new context?","options":[{"text":"Assume the original strategy sponsor represents all frontline needs","why":"A contextual shift can introduce different responsibilities and user requirements.","correct":false,"id":"A"},{"text":"Promise both full projects under the original resources without assessment","why":"The pivot needs realistic trade-offs in effort and delivery.","correct":false,"id":"B"},{"text":"Keep the expansion-study methods unchanged without review","why":"A new operational purpose can need different methods and information.","correct":false,"id":"C"},{"text":"Manage feedback from the newly affected operational stakeholders","why":"A contextual shift can introduce different responsibilities and user requirements.","correct":true,"id":"D"},{"text":"Explain the actual outcome and remaining limits","why":"A truthful account distinguishes planning from completed implementation.","correct":true,"id":"E"},{"text":"Agree a feasible revised scope and explicit exclusions","why":"The pivot needs realistic trade-offs in effort and delivery.","correct":true,"id":"F"},{"text":"Report proposed backlog actions as already delivered","why":"A truthful account distinguishes planning from completed implementation.","correct":false,"id":"G"},{"text":"Reconfirm the decision, urgency and available actions","why":"A new operational purpose can need different methods and information.","correct":true,"id":"H"}],"answer":"A new operational purpose can need different methods and information. The pivot needs realistic trade-offs in effort and delivery. A contextual shift can introduce different responsibilities and user requirements. A truthful account distinguishes planning from completed implementation.","source":{"anchor":"ksb-b7","guideSha256":"d5e4802223d7b6d3188731e9612e51c8f64a5b2d86c85188adaff8506b58ab9d","excerpt":"Describe a change in project scope, organisational direction or responsibilities and how you adapted the plan."},"id":"T49-E2-Q10"}]},{"id":"T50","title":"Publishing and handing over analysis","description":"Connect actual rules, architecture, preparation and shared responsibility.","questions":[{"ksb":"K2","objective":"Release rules","prompt":"In this fictional publishing project, policy permits external aggregates only after a named owner's review. Which release actions comply with that requirement?","options":[{"text":"Clarify uncertainty before distributing the report","why":"A deadline does not replace the specified review requirement.","correct":true,"id":"A"},{"text":"Check included downloads and embedded detail","why":"The authorised review needs to cover the actual information being released, including additional views and export contents.","correct":true,"id":"B"},{"text":"Record the applicable policy and release decision","why":"Technical publication does not establish the required governance decision.","correct":true,"id":"C"},{"text":"Treat successful upload as the owner's approval","why":"Technical publication does not establish the required governance decision.","correct":false,"id":"D"},{"text":"Limit the owner's review to the headline table even though the export includes detailed tabs","why":"The authorised review needs to cover the actual information being released, including additional views and export contents.","correct":false,"id":"E"},{"text":"Publish first because the audience is waiting","why":"A deadline does not replace the specified review requirement.","correct":false,"id":"F"},{"text":"Obtain the relevant review for the actual output","why":"The stated rule concerns review of the output being released.","correct":true,"id":"G"},{"text":"Treat a similar report's past approval as approval of this release","why":"The stated rule concerns review of the output being released.","correct":false,"id":"H"}],"answer":"The stated rule concerns review of the output being released. The authorised review needs to cover the actual information being released, including additional views and export contents. Technical publication does not establish the required governance decision. A deadline does not replace the specified review requirement.","source":{"anchor":"ksb-k2","guideSha256":"2af0f21e6042cbfd7dace272442495693058d5176f45734f41ae666c6d309ebb","excerpt":"Organisational policies translate legal obligations and risk decisions into practical rules."},"id":"T50-E2-Q01"},{"ksb":"S1","objective":"Hidden detail","prompt":"The report's charts are aggregate, but an export contains case identifiers and free-text notes. Which operating actions address the exposure?","options":[{"text":"Recheck permissions and interactive paths before release","why":"Downloads and drill-through can expose different levels of detail.","correct":true,"id":"A"},{"text":"Review and restrict the actual export to the approved purpose","why":"A concealed control does not protect an accessible underlying file.","correct":true,"id":"B"},{"text":"Cover identifiers visually without removing recoverable data","why":"Visual concealment may leave sensitive content accessible.","correct":false,"id":"C"},{"text":"Hide the export button while leaving a publicly accessible file","why":"A concealed control does not protect an accessible underlying file.","correct":false,"id":"D"},{"text":"Retain the unrestricted export publicly for reproducibility","why":"Reproducibility and direct-name removal do not remove relevant disclosure obligations.","correct":false,"id":"E"},{"text":"Remove unnecessary identifying fields through the authorised process","why":"Visual concealment may leave sensitive content accessible.","correct":true,"id":"F"},{"text":"Assume aggregate charts make every related asset safe","why":"Downloads and drill-through can expose different levels of detail.","correct":false,"id":"G"},{"text":"Treat the absence of a name column as proof the notes cannot identify people","why":"Reproducibility and direct-name removal do not remove relevant disclosure obligations.","correct":false,"id":"H"}],"answer":"A concealed control does not protect an accessible underlying file. Visual concealment may leave sensitive content accessible. Downloads and drill-through can expose different levels of detail. Reproducibility and direct-name removal do not remove relevant disclosure obligations.","source":{"anchor":"ksb-s1","guideSha256":"572954ea98dd7ab0915240402eedd246d31250be6c5cd1f8f895c63a7f272b3a","excerpt":"Explain the systems you actually operated and the controls you personally applied throughout the work."},"id":"T50-E2-Q02"},{"ksb":"K4","objective":"Source category","prompt":"The report combines an operational register with licensed open regional statistics. Which description is accurate?","options":[{"text":"An open context table makes the joined personal register open too","why":"The rights and handling of one source do not automatically transfer to another.","correct":false,"id":"A"},{"text":"Public availability proves unrestricted compatibility with every use","why":"Access does not establish either unrestricted rights or analytical comparability.","correct":false,"id":"B"},{"text":"Distinguish the protected source register from any released aggregate","why":"The rights and handling of one source do not automatically transfer to another.","correct":true,"id":"C"},{"text":"Explain which actual source versions were used","why":"A truthful source account distinguishes actual inputs from possible alternatives.","correct":true,"id":"D"},{"text":"Its use in this analysis proves it was originally collected for research","why":"Later analytical use does not change the original operational collection purpose.","correct":false,"id":"E"},{"text":"List unused data categories as integrated inputs","why":"A truthful source account distinguishes actual inputs from possible alternatives.","correct":false,"id":"F"},{"text":"The register has an administrative origin","why":"Later analytical use does not change the original operational collection purpose.","correct":true,"id":"G"},{"text":"Check the open statistics' licence conditions and definitions","why":"Access does not establish either unrestricted rights or analytical comparability.","correct":true,"id":"H"}],"answer":"Later analytical use does not change the original operational collection purpose. Access does not establish either unrestricted rights or analytical comparability. The rights and handling of one source do not automatically transfer to another. A truthful source account distinguishes actual inputs from possible alternatives.","source":{"anchor":"ksb-k4","guideSha256":"66aae08b77f0ffacc180ea12145f440d8fb89c6c19de5dbd5cacd6fe318f340d","excerpt":"These terms describe access, origin or purpose and can overlap: Type Meaning and example Open data Available for reuse under an open licence, subject to its terms; for example, a published licensed aggregate dataset Public data Accessible to the public; availability alone does not establish unrestricted reuse rights Administrative data Generated by delivering services or running operations; for example, service request records Research data Collected or produced for research; for example, survey responses or experimental observations An administrative dataset may later produce an open aggregate release."},"id":"T50-E2-Q03"},{"ksb":"K5","objective":"Narrative coding","prompt":"The register is tabular but contains free-text notes that are coded into themes. Which account describes the transformation correctly?","options":[{"text":"The CSV extension makes every note's meaning fully structured","why":"A tabular container does not eliminate interpretation within narrative content.","correct":false,"id":"A"},{"text":"Theme coding creates derived categorical information","why":"Category codes do not establish a continuous quantitative scale.","correct":true,"id":"B"},{"text":"Explain coding rules and potential loss of context","why":"Coding summarises content and can introduce interpretation limits.","correct":true,"id":"C"},{"text":"Numeric theme IDs automatically measure severity","why":"Category codes do not establish a continuous quantitative scale.","correct":false,"id":"D"},{"text":"A structured table can contain unstructured narrative fields","why":"A tabular container does not eliminate interpretation within narrative content.","correct":true,"id":"E"},{"text":"Describe thematic counts as a perfect copy of every narrative meaning","why":"Coding summarises content and can introduce interpretation limits.","correct":false,"id":"F"},{"text":"Infer that converting notes to counts guarantees anonymous release","why":"Keywords alone may miss synonyms and negation; meaningful coding needs interpretation, and resulting counts can still carry disclosure risks.","correct":false,"id":"G"},{"text":"Treat exact keyword matches as complete themes without checking meaning in context","why":"Keywords alone may miss synonyms and negation; meaningful coding needs interpretation, and resulting counts can still carry disclosure risks.","correct":false,"id":"H"}],"answer":"A tabular container does not eliminate interpretation within narrative content. Category codes do not establish a continuous quantitative scale. Coding summarises content and can introduce interpretation limits. Keywords alone may miss synonyms and negation; meaningful coding needs interpretation, and resulting counts can still carry disclosure risks.","source":{"anchor":"ksb-k5","guideSha256":"23672bf246254bb2cf5242fed10614c8365931ef6c6959372fb995de98cdf639","excerpt":"Structured data follows an explicit schema, usually fields, types and relationships, so records can be queried consistently."},"id":"T50-E2-Q04"},{"ksb":"K6","objective":"Platform roles","prompt":"The register is held in an operational database, transformed into warehouse tables and accessed by a BI client. Which explanation is correct?","options":[{"text":"Claim querying a warehouse proves you designed every source table","why":"Accessing an existing system does not establish design responsibility.","correct":false,"id":"A"},{"text":"Treat a successful query as proof all maintenance duties were performed by the analyst","why":"Consumption and platform maintenance are distinct responsibilities.","correct":false,"id":"B"},{"text":"Distinguish record-keeping storage from analytical reporting structures","why":"The stated components have different storage and consumption roles.","correct":true,"id":"C"},{"text":"Explain relevant keys, transformations and load ordering","why":"The order of transformation and loading distinguishes those workflows.","correct":true,"id":"D"},{"text":"Describe the authorised interface used to retrieve data","why":"Accessing an existing system does not establish design responsibility.","correct":true,"id":"E"},{"text":"Use ETL and ELT interchangeably without describing the sequence","why":"The order of transformation and loading distinguishes those workflows.","correct":false,"id":"F"},{"text":"Describe the BI client as the original transaction database","why":"The stated components have different storage and consumption roles.","correct":false,"id":"G"},{"text":"Explain maintenance responsibilities such as validated loads and permissions","why":"Consumption and platform maintenance are distinct responsibilities.","correct":true,"id":"H"}],"answer":"The stated components have different storage and consumption roles. The order of transformation and loading distinguishes those workflows. Accessing an existing system does not establish design responsibility. Consumption and platform maintenance are distinct responsibilities.","source":{"anchor":"ksb-k6","guideSha256":"382d9dd3a3b7254a9f654221d7aa58635f29ddfd5078b2085841f6e357c13175","excerpt":"Use the terms precisely: Term Explanation Database An organised collection of data managed for storage, retrieval and updates Data warehouse An integrated analytical store, often containing cleaned historical data from several systems Data lake A store for varied raw and processed formats; usefulness still depends on metadata, governance and quality Relational database / RDBMS Data organised in related tables and managed by a relational database management system, commonly queried with SQL NoSQL A family of non-relational approaches, such as document, key-value, graph and wide-column stores Normalisation Structuring relational tables to reduce avoidable duplication and update anomalies; analytical designs may deliberately denormalise ETL Extract data, transform it and load it into a target; ELT loads before transforming Implementation includes deciding record grain, data types, primary/foreign keys, constraints, indexes and access roles."},"id":"T50-E2-Q05"},{"ksb":"K12","objective":"Currency in the release","prompt":"The warehouse last loaded on Monday, and the report refreshed on Wednesday. Which publication context is accurate?","options":[{"text":"Relabel Monday's snapshot as Wednesday data","why":"Accessibility and labels do not establish current or successfully refreshed source content.","correct":false,"id":"A"},{"text":"The report refresh date does not establish Wednesday source observations","why":"A downstream refresh can read the older warehouse snapshot.","correct":true,"id":"B"},{"text":"Identify the upstream dependency and owner if freshness is inadequate","why":"Currency depends on the source-to-report chain, not only the final tool.","correct":true,"id":"C"},{"text":"Infer the charting tool caused every stale-data problem","why":"Currency depends on the source-to-report chain, not only the final tool.","correct":false,"id":"D"},{"text":"Explain the relevant source and refresh periods","why":"A current display timestamp can misrepresent the age of the underlying information.","correct":true,"id":"E"},{"text":"Assume an accessible dashboard proves every upstream load succeeded","why":"Accessibility and labels do not establish current or successfully refreshed source content.","correct":false,"id":"F"},{"text":"Display only the current clock time as data currency","why":"A current display timestamp can misrepresent the age of the underlying information.","correct":false,"id":"G"},{"text":"The report necessarily contains every transaction through Wednesday","why":"A downstream refresh can read the older warehouse snapshot.","correct":false,"id":"H"}],"answer":"A downstream refresh can read the older warehouse snapshot. A current display timestamp can misrepresent the age of the underlying information. Currency depends on the source-to-report chain, not only the final tool. Accessibility and labels do not establish current or successfully refreshed source content.","source":{"anchor":"ksb-k12","guideSha256":"82a19528e64643915c69aafa73db1a3bcd08a4f6a7f6715d3baf0c435f7f4a97","excerpt":"Data architecture describes how sources, storage, transformation, governance and consumption fit together."},"id":"T50-E2-Q06"},{"ksb":"S2","objective":"Lifecycle account","prompt":"The publishing project has a brief, preparation log, analysis, validation and handover. Which account demonstrates the lifecycle coherently?","options":[{"text":"Connect the brief's decision to the chosen methods","why":"A lifecycle explanation should show how the stages served the project purpose.","correct":true,"id":"A"},{"text":"List document names without explaining their relationships","why":"A lifecycle explanation should show how the stages served the project purpose.","correct":false,"id":"B"},{"text":"Explain actual preparation and validation actions","why":"The visible output alone does not demonstrate the work performed earlier.","correct":true,"id":"C"},{"text":"Claim adoption solely because the report was sent","why":"Delivery and actual implementation are different outcomes.","correct":false,"id":"D"},{"text":"Treat a final screenshot as evidence of every preceding stage","why":"The visible output alone does not demonstrate the work performed earlier.","correct":false,"id":"E"},{"text":"Distinguish your contribution from colleagues' work","why":"A lifecycle account should distinguish intentions from actions actually performed and accurately identify responsibility.","correct":true,"id":"F"},{"text":"Describe communication, implementation arrangements and limitations","why":"Delivery and actual implementation are different outcomes.","correct":true,"id":"G"},{"text":"Describe the agreed plan as if it demonstrates that every planned activity was carried out","why":"A lifecycle account should distinguish intentions from actions actually performed and accurately identify responsibility.","correct":false,"id":"H"}],"answer":"A lifecycle explanation should show how the stages served the project purpose. The visible output alone does not demonstrate the work performed earlier. Delivery and actual implementation are different outcomes. A lifecycle account should distinguish intentions from actions actually performed and accurately identify responsibility.","source":{"anchor":"ksb-s2","guideSha256":"1e42a8017fc0a22b3438b81346ad97e890b7b11194c4f4c8cfda20694ed98079","excerpt":"K3 explains the lifecycle; S2 shows that you carried it out."},"id":"T50-E2-Q07"},{"ksb":"S4","objective":"Export grain","prompt":"One source row represents a case, while another contains several notes per case. Which structural adaptation is appropriate for a case-level report?","options":[{"text":"Decide how notes should be summarised or linked at case grain","why":"A one-to-many join can multiply rows without adding case entities.","correct":true,"id":"A"},{"text":"Join all notes and count each resulting row as a separate case","why":"A one-to-many join can multiply rows without adding case entities.","correct":false,"id":"B"},{"text":"Treat both sources as the same grain because they share a case ID","why":"Shared keys and repeated text do not establish identical analytical units.","correct":false,"id":"C"},{"text":"Preserve relevant case identifiers and reconcile counts","why":"Identity is needed for meaningful reconciliation of entities.","correct":true,"id":"D"},{"text":"Remove identifiers before checking whether cases were duplicated","why":"Identity is needed for meaningful reconciliation of entities.","correct":false,"id":"E"},{"text":"Explain any coding or aggregation of the notes","why":"Summarisation can reduce detail and needs an honest explanation.","correct":true,"id":"F"},{"text":"Claim reshaping preserves every narrative detail without loss","why":"Summarisation can reduce detail and needs an honest explanation.","correct":false,"id":"G"},{"text":"Deduplicate note text without considering distinct cases","why":"Shared keys and repeated text do not establish identical analytical units.","correct":false,"id":"H"}],"answer":"A one-to-many join can multiply rows without adding case entities. Identity is needed for meaningful reconciliation of entities. Summarisation can reduce detail and needs an honest explanation. Shared keys and repeated text do not establish identical analytical units.","source":{"anchor":"ksb-s4","guideSha256":"6467e74ee7d9e4c6b7f7cc7ae81972bb70699e72444b1b7ff0df47f9d8a010a4","excerpt":"State the shape, grain, schema, keys and field types of each actual dataset, including row and column counts at the relevant extraction date."},"id":"T50-E2-Q08"},{"ksb":"S8","objective":"Joined release checks","prompt":"The final preparation merges case-level summaries with a one-row-per-service lookup. Which checks should support the release?","options":[{"text":"Assume matching column names prove a one-to-one relationship","why":"Key meaning and multiplicity require checks beyond naming.","correct":false,"id":"A"},{"text":"Validate only whether the query executes","why":"Execution success does not establish coverage or numerical preservation.","correct":false,"id":"B"},{"text":"Verify the intended keys and lookup uniqueness","why":"Key meaning and multiplicity require checks beyond naming.","correct":true,"id":"C"},{"text":"Describe combining sources as automatic proof of improved accuracy","why":"Integration can add benefit while introducing or retaining risks that need explanation.","correct":false,"id":"D"},{"text":"Infer semantic compatibility from matching numeric types","why":"Type compatibility alone does not align meaning, scale or timing.","correct":false,"id":"E"},{"text":"Count unmatched cases and reconcile important totals","why":"Execution success does not establish coverage or numerical preservation.","correct":true,"id":"F"},{"text":"Confirm units, periods and source definitions","why":"Type compatibility alone does not align meaning, scale or timing.","correct":true,"id":"G"},{"text":"Document significant transformations and residual limitations","why":"Integration can add benefit while introducing or retaining risks that need explanation.","correct":true,"id":"H"}],"answer":"Key meaning and multiplicity require checks beyond naming. Execution success does not establish coverage or numerical preservation. Type compatibility alone does not align meaning, scale or timing. Integration can add benefit while introducing or retaining risks that need explanation.","source":{"anchor":"ksb-s8","guideSha256":"0f5cddb86161986b79351977142757eead70691fc156a7d038e573f11ffcd428","excerpt":"Demonstrate a repeatable join in an appropriate tool, with explicit keys, grain and validation."},"id":"T50-E2-Q09"},{"ksb":"B3","objective":"Handover ownership","prompt":"A colleague will maintain the published report, while the source team owns its upstream loads. Which collaboration supports reliable use?","options":[{"text":"Describe your contribution and the observed benefit accurately","why":"A truthful account separates your work from wider team responsibilities.","correct":true,"id":"A"},{"text":"Claim the entire platform operation as your personal work","why":"A truthful account separates your work from wider team responsibilities.","correct":false,"id":"B"},{"text":"Share suitable documentation and check understanding","why":"A useful handover needs adequate information and feedback on understanding.","correct":true,"id":"C"},{"text":"Explain the maintainer's tasks and source dependencies","why":"Ownership should follow agreed roles rather than incidental interaction.","correct":true,"id":"D"},{"text":"Assign all responsibility to whoever last opened the report","why":"Ownership should follow agreed roles rather than incidental interaction.","correct":false,"id":"E"},{"text":"Treat sending a folder as proof the colleague can operate the workflow","why":"A useful handover needs adequate information and feedback on understanding.","correct":false,"id":"F"},{"text":"Change upstream production schedules without involving their owner","why":"Dependencies should be managed through the responsible team.","correct":false,"id":"G"},{"text":"Coordinate issue routes with the source team","why":"Dependencies should be managed through the responsible team.","correct":true,"id":"H"}],"answer":"Ownership should follow agreed roles rather than incidental interaction. A useful handover needs adequate information and feedback on understanding. Dependencies should be managed through the responsible team. A truthful account separates your work from wider team responsibilities.","source":{"anchor":"ksb-b3","guideSha256":"ed7a422a0cad1868dc9d98971b13d412dba7ea1d5b5578a0c8dd2a7a5f18c359","excerpt":"Explain how you organised and delivered your own responsibilities, recognised when others' expertise mattered and coordinated dependencies."},"id":"T50-E2-Q10"}]}]);d.revisedPackSha256["revised-4"]="c3051a0be37281f3fa8222ee799769d76c61e19c6492cc244a7c1499e3f25daf";})();
